INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('toan', 'Toán học 12', '', 'CHƯƠNG 1', 'Toán học 12: Ứng dụng đạo hàm khảo sát hàm số', 'Tính đơn điệu, cực trị, GTLN - GTNN, đường tiệm cận đứng / ngang / xiên của đồ thị hàm số và bài toán thực tế.', 'TRẦN ĐĂNG KHOA', 1) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('vatli', 'Vật lí 12', '', 'CHƯƠNG 1', 'Vật lí 12: Chuyên đề Vật lí nhiệt', 'Mô hình động học phân tử, cấu trúc 3 thể, các quá trình chuyển thể và định luật nhiệt động lực học.', 'TRẦN ĐĂNG KHOA', 2) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('hoa', 'Hóa học 12', '', 'CHƯƠNG 1', 'Hóa học 12: Este - Lipit - Xà phòng & Chất giặt rửa', 'Cấu tạo đồng phân danh pháp Este, phản ứng xà phòng hóa, chất béo Triglyceride và cơ chế tẩy rửa.', 'TRẦN ĐĂNG KHOA', 3) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('sinh', 'Sinh học 12', '', 'PHẦN 4', 'Sinh học 12: Di truyền phân tử & Nhiễm sắc thể', 'Mã di truyền, tái bản ADN, phiên mã, dịch mã, điều hòa hoạt động gen Operon Lac và đột biến NST.', 'TRẦN ĐĂNG KHOA', 4) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('tinhoc', 'Tin học 12', '', 'CHUYÊN ĐỀ', 'Tin học 12: Khoa học máy tính & Mạng máy tính', 'Hệ thống mạng máy tính, giao thức TCP/IP, thuật toán, cơ sở dữ liệu quan hệ SQL và ứng dụng công nghệ trí tuệ nhân tạo (AI).', 'TRẦN ĐĂNG KHOA', 5) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('nguvan', 'Ngữ văn 12', '', 'CHUYÊN ĐỀ', 'Ngữ văn 12: Đọc hiểu văn bản & Kỹ năng viết nghị luận', 'Kỹ năng đọc hiểu văn bản văn học, nghị luận văn học, nghị luận xã hội, phát triển tư duy phản biện và phong cách ngôn ngữ.', 'TRẦN ĐĂNG KHOA', 6) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('lichsu', 'Lịch Sử 12', '', 'CHUYÊN ĐỀ', 'Lịch Sử 12: Lịch sử thế giới & Lịch sử Việt Nam hiện đại', 'Trật tự thế giới sau Chiến tranh lạnh, Liên Hợp Quốc, ASEAN, các mốc lịch sử cách mạng Việt Nam và công cuộc Đổi mới.', 'TRẦN ĐĂNG KHOA', 7) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.subjects (id, name, badge, corner, hero_title, hero_desc, author, order_index) VALUES ('ngoaingu', 'Ngoại ngữ 12', '', 'GLOBAL SUCCESS', 'Ngoại ngữ 12: Life Stories, Diversity of Culture & Green Living', 'Ngân hàng câu hỏi bám sát cấu trúc đề tốt nghiệp mới: Ngữ pháp thời thì, mạo từ, dạng từ (Word forms), giới từ và điền từ khuyết.', 'TRẦN ĐĂNG KHOA', 8) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hero_title = EXCLUDED.hero_title, hero_desc = EXCLUDED.hero_desc;
INSERT INTO public.topics (id, subject_id, index_code, title, description, chapter, theme, icon_svg, is_full, order_index) VALUES ('1', 'tinhoc', '01', 'Bài 1: Làm quen với trí tuệ nhân tạo', 'Khái niệm AI, các đặc trưng cơ bản, phân biệt AI với tự động hóa, lợi ích và cảnh báo.', 'Chủ đề 1: Trí tuệ nhân tạo (AI)', 'blue', '<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2a4 4 0 0 1 4 4c0 1.95-1.4 3.58-3.25 3.93l-.25.04v2.03h2.5a2.5 2.5 0 0 1 2.45 2H18a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2h-1v1a2 2 0 0 1-2 2h-6a2 2 0 0 1-2-2v-1H6a2 2 0 0 1-2-2v-2a2 2 0 0 1 2-2h.55a2.5 2.5 0 0 1 2.45-2h2.5V9.97l-.25-.04A4 4 0 0 1 8 6a4 4 0 0 1 4-4z"/><circle cx="9" cy="17" r="1"/><circle cx="15" cy="17" r="1"/></svg>', false, 1) ON CONFLICT (subject_id, id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, chapter = EXCLUDED.chapter;
INSERT INTO public.topics (id, subject_id, index_code, title, description, chapter, theme, icon_svg, is_full, order_index) VALUES ('2', 'tinhoc', '02', 'Bài 2: Trí tuệ nhân tạo trong khoa học và đời sống', 'Ứng dụng trong y tế, giáo dục, giao thông, khoa học; vấn đề thiên lệch dữ liệu, hộp đen và đạo đức AI.', 'Chủ đề 1: Trí tuệ nhân tạo (AI)', 'purple', '<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>', false, 2) ON CONFLICT (subject_id, id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, chapter = EXCLUDED.chapter;
INSERT INTO public.topics (id, subject_id, index_code, title, description, chapter, theme, icon_svg, is_full, order_index) VALUES ('3', 'tinhoc', '03', 'Bài 3: Một số thiết bị mạng thông dụng', 'Đặc điểm và chức năng của Hub, Switch, Router, Modem, WAP; cáp xoắn đôi RJ45 và thiết kế mạng LAN.', 'Chủ đề 2: Mạng máy tính và Internet', 'green', '<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="2" width="20" height="8" rx="2" ry="2"/><rect x="2" y="14" width="20" height="8" rx="2" ry="2"/><line x1="6" y1="6" x2="6.01" y2="6"/><line x1="6" y1="18" x2="6.01" y2="18"/></svg>', false, 3) ON CONFLICT (subject_id, id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, chapter = EXCLUDED.chapter;
INSERT INTO public.topics (id, subject_id, index_code, title, description, chapter, theme, icon_svg, is_full, order_index) VALUES ('4', 'tinhoc', '04', 'Bài 4: Giao thức mạng', 'Bộ giao thức TCP/IP, địa chỉ IPv4, chuyển đổi nhị phân, DNS, HTTP/HTTPS, phân biệt IP và MAC.', 'Chủ đề 2: Mạng máy tính và Internet', 'amber', '<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>', false, 4) ON CONFLICT (subject_id, id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, chapter = EXCLUDED.chapter;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_001', 'tinhoc', '1', 'mc', 'Thuật ngữ ''Trí tuệ nhân tạo'' (Artificial Intelligence - AI) được hiểu chính xác nhất là gì theo chương trình Tin học 12?', '["Khả năng máy tính hoạt động hoàn toàn độc lập mà không cần bất kỳ nguồn điện hay phần cứng hỗ trợ nào.","Khả năng của hệ thống máy tính có thể thực hiện các công việc đòi hỏi trí thông minh của con người.","Tập hợp tất cả các thuật toán tính toán số học tốc độ cao trên siêu máy tính.","Phần mềm soạn thảo và quản trị cơ sở dữ liệu nâng cao được tự động hóa."]'::jsonb, 1, 'Theo SGK Tin học 12, Trí tuệ nhân tạo (AI) là khả năng của hệ thống máy tính có thể thực hiện các công việc đòi hỏi trí thông minh của con người.', 1) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_002', 'tinhoc', '1', 'mc', 'Đặc trưng nào sau đây không phải là một trong các đặc trưng cơ bản của hệ thống Trí tuệ nhân tạo?', '["Khả năng học hỏi từ dữ liệu và kinh nghiệm.","Khả năng nhận thức môi trường qua thị giác, âm thanh hoặc cảm biến.","Khả năng tự tạo ra cảm xúc hỷ nộ ái ố và ý thức tâm linh như con người.","Khả năng suy luận, giải quyết vấn đề và xử lí ngôn ngữ tự nhiên."]'::jsonb, 2, 'Hệ thống AI hiện nay không có cảm xúc, ý thức tâm linh hay tình cảm thực sự như con người.', 2) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_003', 'tinhoc', '1', 'mc', 'Thuật ngữ ''Học máy'' (Machine Learning) gắn liền trực tiếp nhất với đặc trưng nào của AI?', '["Khả năng tự động cải thiện hiệu suất thực hiện nhiệm vụ thông qua việc xử lí và huấn luyện trên dữ liệu.","Khả năng sao lưu dữ liệu máy tính lên đám mây định kỳ.","Khả năng chạy nhiều chương trình cùng lúc trên hệ điều hành đa nhiệm.","Khả năng bảo vệ máy tính khỏi sự tấn công của mã độc và virus."]'::jsonb, 0, 'Học máy (Machine Learning) là khả năng của máy tính tự cải thiện hiệu quả làm việc thông qua quá trình học hỏi từ dữ liệu.', 3) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_004', 'tinhoc', '1', 'mc', 'Lĩnh vực nào của AI tập trung vào việc giúp máy tính hiểu, diễn giải và tạo ra ngôn ngữ giống như con người?', '["Thị giác máy tính (Computer Vision).","Xử lí ngôn ngữ tự nhiên (Natural Language Processing - NLP).","Hệ thống nhúng (Embedded Systems).","Mạng nơ-ron bán dẫn (Hardware Neural Networks)."]'::jsonb, 1, 'Xử lí ngôn ngữ tự nhiên (NLP) là nhánh của AI giúp máy tính hiểu, phân tích và giao tiếp bằng ngôn ngữ của con người.', 4) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_005', 'tinhoc', '1', 'mc', 'Hệ thống AI hiện nay đang được ứng dụng rộng rãi trong thực tế thuộc loại nào?', '["AI tổng quát (AGI) có năng lực tư duy vượt trội con người về mọi mặt.","Siêu trí tuệ nhân tạo (Super AI) có khả năng tự nhận thức độc lập.","AI hẹp (Narrow AI / Weak AI) chuyên giải quyết tốt một hoặc một nhóm bài toán cụ thể.","AI vô thức (Unconscious AI) không cần xử lí dữ liệu đầu vào."]'::jsonb, 2, 'Tất cả các ứng dụng AI hiện nay trong thực tế đều là AI hẹp (Narrow AI), được thiết kế để giải quyết một nhiệm vụ chuyên biệt cụ thể.', 5) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_006', 'tinhoc', '1', 'mc', 'Điểm khác biệt mấu chốt giữa một hệ thống AI và một chương trình tự động hóa truyền thống là:', '["Chương trình truyền thống chạy theo chuỗi lệnh cố định được lập trình trước, còn AI có thể thích nghi và học từ dữ liệu để đưa ra dự đoán/quyết định.","Chương trình truyền thống không cần phần cứng để chạy.","AI luôn cho ra kết quả chính xác tuyệt đối 100% trong mọi trường hợp, còn chương trình truyền thống thì không.","Chương trình truyền thống xử lí văn bản, còn AI chỉ xử lí được chữ số."]'::jsonb, 0, 'Chương trình truyền thống thực hiện chính xác theo quy tắc lập trình cứng, trong khi AI có thể học hỏi và tự thích nghi với dữ liệu mới.', 6) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_007', 'tinhoc', '1', 'mc', 'Một chiếc máy sấy tay tự động trong nhà vệ sinh bật quạt gió khi có người đưa tay vào dựa trên cảm biến hồng ngoại. Thiết bị này:', '["Là hệ thống AI hoàn chỉnh vì nó nhận biết được bàn tay người qua cảm biến.","Không phải là AI, vì đây chỉ là mạch cảm ứng đóng ngắt mạch điện cơ bản theo ngưỡng vật lý cố định.","Là một hệ thống thị giác máy tính cao cấp có khả năng học sâu.","Là AI tổng quát vì thay thế được hành vi lấy khăn lau tay của con người."]'::jsonb, 1, 'Máy sấy tay chỉ hoạt động theo nguyên lý cảm biến ngắt/mở mạch điện theo ngưỡng vật lý cố định, không có khả năng học hỏi hay suy luận của AI.', 7) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_008', 'tinhoc', '1', 'mc', 'Phát biểu nào sau đây đúng khi so sánh giữa trí tuệ con người và trí tuệ nhân tạo hiện nay?', '["AI có khả năng xử lí và ghi nhớ khối lượng dữ liệu khổng lồ nhanh hơn con người nhưng thiếu khả năng cảm thụ nghệ thuật và tư duy đạo đức thực thụ.","Con người không thể đưa ra suy luận logic nhanh bằng bất kỳ ứng dụng AI nào.","AI hiện nay đã hoàn toàn sở hữu ý thức và tự chịu trách nhiệm pháp lý trước pháp luật.","Trí thông minh của AI không phụ thuộc vào dữ liệu do con người cung cấp hoặc thiết kế."]'::jsonb, 0, 'AI vượt trội về tốc độ tính toán và dung lượng bộ nhớ dữ liệu lớn, nhưng không có ý thức, cảm thụ nghệ thuật hay tư duy đạo đức như con người.', 8) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_009', 'tinhoc', '1', 'mc', 'Ứng dụng nào sau đây thể hiện rõ nét nhất khả năng ''Thị giác máy tính'' (Computer Vision) của AI?', '["Ứng dụng lọc thư rác dựa trên các từ khóa nhạy cảm trong hòm thư điện tử.","Ứng dụng tự động nhận diện biển số xe vi phạm giao thông và khuôn mặt người lái qua camera giám sát.","Phần mềm Microsoft Excel tự động tính hàm SUM trên một cột điểm số.","Trang web bán hàng trực tuyến hiển thị thông báo giảm giá vào dịp Tết."]'::jsonb, 1, 'Nhận diện biển số và khuôn mặt từ hình ảnh/video là ứng dụng tiêu biểu của Thị giác máy tính (Computer Vision).', 9) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_010', 'tinhoc', '1', 'mc', 'Thuật toán gợi ý video trên YouTube học hỏi từ lịch sử xem, thời gian dừng lại trên video và tương tác của người dùng để đề xuất nội dung tiếp theo. Đây là minh chứng cho đặc trưng nào của AI?', '["Khả năng tự tạo ra bản quyền sáng chế mới.","Khả năng học hỏi từ hành vi và dữ liệu thực tế để tối ưu hóa quyết định.","Khả năng vận hành thiết bị ngoại vi không cần nguồn điện.","Khả năng thay thế toàn bộ lập trình viên phần mềm máy tính."]'::jsonb, 1, 'Thuật toán đề xuất minh họa cho khả năng học hỏi từ dữ liệu hành vi của người dùng để cải thiện độ chính xác của dự đoán.', 10) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_011', 'tinhoc', '1', 'mc', 'Một phần mềm chơi cờ vua tự động sử dụng giải thuật Minimax cổ điển không cập nhật chiến thuật sau các ván thua khác với hệ thống AI AlphaZero ở điểm nào?', '["Minimax là AI tự học qua hàng triệu ván cờ, còn AlphaZero chỉ dùng luật cố định.","AlphaZero áp dụng học tăng cường (Reinforcement Learning) để tự chơi với chính mình và nâng cao trình độ, còn Minimax thuần túy vét cạn theo quy tắc cứng.","AlphaZero cần sự hỗ trợ của con người khi thi đấu trực tiếp.","Cả hai hệ thống đều là AI tổng quát có cảm xúc khi chiến thắng."]'::jsonb, 1, 'AlphaZero sử dụng kỹ thuật học tăng cường (Reinforcement Learning) tự chơi hàng triệu ván để tự khám phá chiến thuật mới, khác biệt với tìm kiếm vét cạn cứng.', 11) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_012', 'tinhoc', '1', 'mc', 'Khi sử dụng trợ lý ảo như Siri hoặc Google Assistant, người dùng nói ''Thời tiết hôm nay thế nào?'', trợ lý ảo trả lời bằng giọng nói và hiển thị nhiệt độ. Quá trình này đã phối hợp các năng lực AI nào?', '["Nhận dạng giọng nói (Speech-to-Text), xử lí ngôn ngữ tự nhiên (NLP) và tổng hợp giọng nói (Text-to-Speech).","Đồ họa vector 3D và giải mã tín hiệu vô tuyến tương tự.","Nén tập tin nhị phân và mã hóa đường truyền TCP.","Định tuyến mạng Internet và đồng bộ hóa xung nhịp CPU."]'::jsonb, 0, 'Trợ lý ảo kết hợp chuyển đổi giọng nói thành văn bản, phân tích hiểu ý định bằng NLP và chuyển phản hồi thành tiếng nói nhân tạo.', 12) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_013', 'tinhoc', '1', 'mc', 'Khẳng định nào sau đây là sai khi nói về giới hạn của Trí tuệ nhân tạo ở thời điểm hiện tại?', '["AI có thể đưa ra kết quả sai lệch nếu tập dữ liệu huấn luyện đầu vào bị thiên vị (bias).","AI có thể gặp hiện tượng ''ảo giác'' (hallucination), tự tạo ra thông tin không có thật nhưng trình bày rất thuyết phục.","AI hiện nay có thể hiểu sâu sắc ngữ cảnh văn hóa, đạo đức và sự đồng cảm như một bác sĩ tâm lý con người.","AI phụ thuộc chặt chẽ vào dữ liệu huấn luyện và tài nguyên tính toán phần cứng."]'::jsonb, 2, 'AI không có cảm xúc, không trải nghiệm tâm lý thực tế nên không thể thấu cảm sâu sắc như con người.', 13) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_014', 'tinhoc', '1', 'mc', 'Một bệnh viện cài đặt máy đo thân nhiệt tự động ở cửa ra vào. Khi nhiệt độ vượt quá 37.5°C, còi hú vang lên. Trường hợp này:', '["Là ứng dụng AI chuyên sâu trong chẩn đoán lâm sàng bệnh truyền nhiễm.","Là thiết bị tự động hóa điều khiển theo điều kiện logic rẽ nhánh đơn giản (T > 37.5), không phải AI.","Là hệ thống xử lí ngôn ngữ tự nhiên kết hợp mạng nơ-ron nhân tạo.","Là AI hẹp vì nó biết phân biệt giữa người sốt và người không sốt."]'::jsonb, 1, 'So sánh giá trị đo được với một ngưỡng cố định là cấu trúc rẽ nhánh điều kiện cơ bản của tự động hóa, không phải trí tuệ nhân tạo.', 14) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_015', 'tinhoc', '1', 'mc', 'Trong các trường hợp sau, đâu là ví dụ tiêu biểu của việc áp dụng AI hỗ trợ học tập cá nhân hóa?', '["Tải một tệp tài liệu PDF bài tập về máy tính cá nhân để tự in ra giấy giải.","Xem video bài giảng được ghi hình sẵn tải lên nền tảng trực tuyến.","Hệ thống học tập trực tuyến tự động phân tích các câu hỏi học sinh làm sai, từ đó đề xuất lộ trình và bài tập bổ trợ phù hợp riêng với năng lực của học sinh đó.","Tham gia một nhóm mạng xã hội để trao đổi lời giải bài tập với bạn bè."]'::jsonb, 2, 'Hệ thống phân tích điểm yếu học sinh để tự động điều chỉnh lộ trình riêng biệt là bản chất của học tập cá nhân hóa bằng AI.', 15) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_016', 'tinhoc', '1', 'mc', 'Khi một bức ảnh chụp bài toán hình học được tải lên ứng dụng học tập, ứng dụng chuyển ảnh thành văn bản đề bài rồi gợi ý lời giải. Công nghệ AI nào được sử dụng ở bước trích xuất đề bài?', '["Nhận dạng ký tự quang học (OCR) dựa trên thị giác máy tính.","Giao thức truyền tệp FTP qua Internet.","Thuật toán nén dữ liệu Lossless JPEG.","Bộ chuyển đổi tín hiệu tương tự sang số (ADC)."]'::jsonb, 0, 'OCR (Optical Character Recognition) là công nghệ thị giác máy tính giúp nhận dạng chữ viết và công thức từ hình ảnh.', 16) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_017', 'tinhoc', '1', 'mc', 'Một dây chuyền đóng chai nước suối tự động dừng lại khi cảm biến quang học nhận thấy chai bị vơi nước dưới vạch quy định. Kỹ sư muốn nâng cấp dây chuyền này thành ứng dụng AI. Đâu là giải pháp phù hợp nhất?', '["Thay cảm biến bằng camera thông minh có khả năng nhận diện chai bị nứt vi mô, nhãn dán bị lệch hoặc phát hiện dị vật biến đổi bất thường qua mô hình học máy.","Tăng tốc độ băng chuyền lên gấp đôi và thay bóng đèn sợi đốt bằng đèn huỳnh quang.","Lắp thêm còi báo động công suất lớn hơn khi có chai lỗi.","Đổi ngôn ngữ hiển thị trên màn hình điều khiển từ tiếng Anh sang tiếng Việt."]'::jsonb, 0, 'Sử dụng camera thông minh tích hợp mô hình thị giác máy tính để phát hiện các lỗi bất thường phức tạp là giải pháp nâng cấp thành hệ thống AI thực thụ.', 17) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_018', 'tinhoc', '1', 'mc', 'Công cụ ChatGPT hay Gemini hiện nay được phân loại vào nhóm công nghệ AI nào sau đây?', '["AI phân loại hình ảnh cổ điển.","AI tạo sinh (Generative AI) dựa trên các mô hình ngôn ngữ lớn (LLM).","Hệ thống cơ sở dữ liệu quan hệ phân tán.","Phần mềm biên dịch mã nguồn hệ thống."]'::jsonb, 1, 'ChatGPT và Gemini là các mô hình AI tạo sinh (Generative AI) phát triển từ mô hình ngôn ngữ lớn (Large Language Model - LLM).', 18) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_019', 'tinhoc', '1', 'mc', 'Một trang web bán hàng hiển thị câu chào: ''Chào buổi sáng, Nguyễn Văn A'' vào lúc 8 giờ sáng sau khi người dùng đăng nhập. Đây có phải là ứng dụng AI không? Vì sao?', '["Phải, vì trang web biết suy luận thời gian trong ngày và biết tên người dùng.","Không, đây chỉ là câu lệnh điều kiện lập trình cơ bản lấy giờ hệ thống và trường tên trong cơ sở dữ liệu.","Phải, vì trang web có khả năng tương tác với con người bằng ngôn ngữ tự nhiên.","Không, trừ khi trang web đó được kết nối bằng đường truyền cáp quang tốc độ cao."]'::jsonb, 1, 'Hiển thị câu chào theo giờ hệ thống chỉ là lập trình logic rẽ nhánh thông thường dựa trên đồng hồ máy tính.', 19) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_020', 'tinhoc', '1', 'mc', 'Robot hút bụi thông minh trong gia đình sử dụng cảm biến LiDAR và thuật toán SLAM để lập bản đồ căn phòng, tự động né chướng ngại vật thay đổi vị trí và ghi nhớ khu vực đã làm sạch. Robot này:', '["Thuần túy là cơ cấu cơ học đóng ngắt rơ-le định kỳ.","Ứng dụng AI ở khả năng nhận thức không gian môi trường, học hỏi và lập kế hoạch đường đi tối ưu.","Đã đạt tới cấp độ trí tuệ nhân tạo tổng quát có nhận thức độc lập.","Không liên quan gì đến AI vì hoạt động dựa trên năng lượng pin sạc."]'::jsonb, 1, 'Khả năng nhận thức môi trường không gian xung quanh và lập kế hoạch đường đi tối ưu là đặc trưng cơ bản của hệ thống AI trong robot thông minh.', 20) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_021', 'tinhoc', '1', 'mc', 'Một bạn học sinh dùng công cụ AI tạo ảnh nghệ thuật để tham gia cuộc thi vẽ tranh kỹ thuật số mà không chỉnh sửa hay ghi nguồn, sau đó tuyên bố mình là tác giả duy nhất. Hành vi này vi phạm vấn đề nào nghiêm trọng nhất khi sử dụng AI?', '["Tính bảo mật phần cứng máy tính.","Đạo đức học thuật, tính trung thực và quyền tác giả/sở hữu trí tuệ.","Tốc độ truyền tải dữ liệu trên đường truyền mạng.","Tiêu chuẩn quốc tế về nén ảnh kỹ thuật số."]'::jsonb, 1, 'Tuyên bố tranh do AI sinh ra là tác phẩm của riêng mình mà không công bố trung thực vi phạm nghiêm trọng tính trung thực học thuật và bản quyền tác giả.', 21) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_022', 'tinhoc', '1', 'mc', 'Trong lĩnh vực giao thông thông minh, xe tự hành (self-driving car) đưa ra quyết định đánh lái hay phanh gấp trong tích tắc dựa vào sự kết hợp của:', '["Thị giác máy tính nhận dạng biển báo, cảm biến phân tích khoảng cách và mô hình suy luận thời gian thực.","Bản đồ in trên giấy và sự điều khiển từ xa của người vận hành qua sóng FM.","Việc tra cứu hướng dẫn sử dụng xe từ sách hướng dẫn điện tử dạng PDF.","Hệ thống định vị vệ tinh đơn thuần mà không cần bất kỳ cảm biến nào gắn trên thân xe."]'::jsonb, 0, 'Xe tự hành kết hợp thị giác máy tính, cảm biến và mô hình suy luận để đưa ra quyết định lái xe an toàn thời gian thực.', 22) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_023', 'tinhoc', '1', 'mc', 'Hiện tượng ''thiên lệch dữ liệu'' (Data Bias) trong các hệ thống AI tuyển dụng nhân sự có thể dẫn đến hậu quả gì?', '["Máy tính tiêu tốn gấp đôi điện năng khi xử lí hồ sơ xin việc.","Hệ thống phân biệt đối xử thiếu công bằng đối với một nhóm ứng viên dựa trên giới tính, vùng miền hoặc chủng tộc do dữ liệu quá khứ bị lệch.","Tốc độ quét hồ sơ bị chậm do tràn bộ nhớ đệm RAM.","Toàn bộ cơ sở dữ liệu ứng viên bị mã hóa độc hại tống tiền."]'::jsonb, 1, 'Thiên lệch dữ liệu khiến mô hình AI học các định kiến sai lệch trong quá khứ, dẫn đến việc phân biệt đối xử bất công khi đánh giá ứng viên mới.', 23) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_024', 'tinhoc', '1', 'mc', 'Ứng dụng dịch tự động Google Translate khi dịch câu ''Bà ấy là một bác sĩ giỏi, còn ông ấy là một y tá tận tụy'' sang một số ngôn ngữ có phân biệt giống từ có thể vô tình gán bác sĩ là nam và y tá là nữ. Nguyên nhân sâu xa của hiện tượng này là gì?', '["Mô hình AI bị lỗi kết nối mạng Internet trong lúc dịch.","Dữ liệu văn bản lịch sử dùng để huấn luyện mô hình chứa định kiến nghề nghiệp theo giới tính của xã hội.","Phần mềm cố tình hạ thấp uy tín của người dùng.","Bộ vi xử lý của máy chủ dịch thuật bị quá tải nhiệt độ."]'::jsonb, 1, 'AI học từ dữ liệu văn bản lịch sử vốn đã tồn tại sẵn các định kiến xã hội, dẫn đến kết quả dịch thuật bị thiên lệch.', 24) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_025', 'tinhoc', '1', 'mc', 'Một bạn học sinh sử dụng AI để giải bài tập Tin học. Cách sử dụng nào sau đây thể hiện thái độ học tập đúng đắn và phát triển năng lực tư duy tốt nhất?', '["Sao chép nguyên văn lời giải do AI cung cấp vào vở nộp cho giáo viên để đạt điểm tối đa.","Nhờ AI viết hộ toàn bộ mã nguồn dự án mà không cần đọc hiểu từng dòng lệnh.","Sử dụng AI như một người trợ giảng: yêu cầu giải thích giải thuật, phân tích ưu nhược điểm của các phương pháp và tự mình viết lại code.","Tin tưởng tuyệt đối 100% mọi kết quả AI trả về mà không cần đối chiếu lại sách giáo khoa."]'::jsonb, 2, 'Thái độ học tập đúng đắn là xem AI như công cụ hỗ trợ tư duy, đối chiếu kiến thức và tự mình rèn luyện kỹ năng giải quyết vấn đề.', 25) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_026', 'tinhoc', '1', 'mc', 'Tại một siêu thị, hệ thống camera tính toán mật độ khách hàng đứng trước từng quầy hàng theo thời gian thực để tự động đề xuất ban quản lý mở thêm quầy thu ngân. Đây là ví dụ về:', '["Hệ thống AI kết hợp thị giác máy tính và hỗ trợ ra quyết định.","Hệ điều hành mạng cục bộ thông thường.","Thiết bị lưu trữ dữ liệu ngoại vi chuẩn USB 3.0.","Phần mềm quét mã vạch tĩnh đơn giản."]'::jsonb, 0, 'Hệ thống tự động đếm người qua camera và phân tích để hỗ trợ quản lý điều phối nhân sự là sự kết hợp giữa thị giác máy tính và hệ hỗ trợ ra quyết định.', 26) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_027', 'tinhoc', '1', 'mc', 'Một công ty quảng cáo tuyên bố: ''Hệ thống điều hòa nhiệt độ của chúng tôi có AI siêu việt vì tự tắt khi nhiệt độ phòng đạt 25°C và bật lại khi nhiệt độ lên 27°C''. Dưới góc độ khoa học máy tính, nhận định này là:', '["Hoàn toàn chính xác vì điều hòa đã tự đưa ra quyết định thay con người.","Quảng cáo phóng đại (thổi phồng AI), vì đây chỉ là bộ rơ-le nhiệt cơ học hoặc vi điều khiển theo ngưỡng cố định đã có từ hàng chục năm trước.","Đúng vì điều hòa sử dụng mạng nơ-ron sâu để học nhiệt độ môi trường.","Đúng vì thiết bị có khả năng suy luận logic mờ phức tạp."]'::jsonb, 1, 'Đóng ngắt theo ngưỡng nhiệt độ rơ-le cố định là kỹ thuật điều khiển tự động hóa cơ bản, không có các đặc trưng thông minh của AI.', 27) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_028', 'tinhoc', '1', 'mc', 'Thuật toán lọc nội dung bạo lực trên mạng xã hội Facebook tự động gỡ bỏ hình ảnh vi phạm chỉ sau vài giây đăng tải. Năng lực cốt lõi giúp hệ thống thực hiện điều này ở quy mô hàng tỷ người dùng là:', '["Hàng triệu nhân viên con người ngồi bấm phím kiểm duyệt thủ công từng ảnh.","Mô hình thị giác máy tính được huấn luyện trên hàng triệu bức ảnh mẫu để phân loại nội dung vi phạm tự động ở tốc độ cao.","Giao thức chuyển đổi địa chỉ IP trên mạng diện rộng.","Phần mềm diệt virus quét mã độc nhị phân bên trong tệp ảnh."]'::jsonb, 1, 'Mô hình thị giác máy tính học sâu (Deep Learning) cho phép nhận diện đặc trưng ảnh vi phạm tự động ở quy mô lớn với tốc độ cao.', 28) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_029', 'tinhoc', '1', 'mc', 'Một học sinh hỏi mô hình ngôn ngữ lớn một sự kiện lịch sử không có thật: ''Chiến dịch Điện Biên Phủ diễn ra năm 1980 có ý nghĩa gì?'', AI vẫn tạo ra một bài luận phân tích rất trôi chảy về chiến dịch năm 1980. Hiện tượng này minh chứng cho vấn đề gì của AI?', '["Hiện tượng ''ảo giác'' (hallucination) – tạo ra thông tin sai sự thật với văn phong tự tin và mạch lạc.","Khả năng ghi nhớ siêu việt của máy tính lượng tử.","Lỗi mất gói tin trong giao thức TCP/IP.","Tính năng bảo mật thông tin tuyệt đối của các hệ thống AI thương mại."]'::jsonb, 0, 'Hiện tượng bịa đặt thông tin sai sự thật nhưng diễn đạt mạch lạc và tự tin được gọi là hiện tượng ''ảo giác'' (hallucination) của mô hình ngôn ngữ lớn.', 29) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_030', 'tinhoc', '1', 'mc', 'Trước sự phát triển nhanh chóng của các công cụ Trí tuệ nhân tạo, kỹ năng nào sau đây là quan trọng nhất đối với một công dân số học sinh phổ thông?', '["Học thuộc lòng toàn bộ các đoạn mã nguồn do AI sinh ra.","Tư duy phản biện để đánh giá, kiểm chứng độ tin cậy của thông tin và năng lực ra lệnh (prompting) hiệu quả, có trách nhiệm.","Tẩy chay hoàn toàn mọi phần mềm có gắn nhãn trí tuệ nhân tạo.","Để AI quyết định thay mọi vấn đề quan trọng trong đời sống cá nhân."]'::jsonb, 1, 'Tư duy phản biện, kiểm chứng thông tin và sử dụng AI có trách nhiệm là năng lực số cốt lõi của học sinh trong thời đại mới.', 30) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_031', 'tinhoc', '2', 'mc', 'Trong lĩnh vực y tế, Trí tuệ nhân tạo đã chứng minh được hiệu quả vượt trội trong công việc nào sau đây?', '["Thay thế hoàn toàn bác sĩ trưởng khoa thực hiện các ca phẫu thuật phức tạp mà không cần giám sát.","Hỗ trợ phân tích ảnh chụp X-quang, MRI, CT để phát hiện sớm các khối u và tổn thương nhỏ.","Tự động kê đơn thuốc kháng sinh liều cao mà không cần chẩn đoán lâm sàng.","Chịu toàn bộ trách nhiệm dân sự và hình sự khi xảy ra tai biến y khoa."]'::jsonb, 1, 'AI hỗ trợ đắc lực bác sĩ trong chẩn đoán hình ảnh (phát hiện tổn thương, tế bào ung thư sớm), giúp tăng độ chính xác của chẩn đoán.', 31) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_032', 'tinhoc', '2', 'mc', 'Đóng góp nổi bật nhất của hệ thống AI AlphaFold (do DeepMind phát triển) đối với nghiên cứu khoa học sinh học là gì?', '["Tự động lai tạo ra các giống lúa biến đổi gen trong phòng thí nghiệm.","Dự đoán chính xác cấu trúc 3D của hàng trăm triệu protein từ chuỗi axit amin.","Thay thế kính hiển vi quang học trong việc quan sát tế bào sống.","Tiêu diệt trực tiếp các loại vi khuẩn gây bệnh trong máu bệnh nhân."]'::jsonb, 1, 'AlphaFold giải quyết bài toán dự đoán cấu trúc 3D của protein từ chuỗi axit amin, tạo bước đột phá lịch sử trong sinh học phân tử.', 32) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_033', 'tinhoc', '2', 'mc', 'Trong lĩnh vực giáo dục, ứng dụng nào sau đây thể hiện rõ nét nhất vai trò tích cực của AI?', '["Tự động làm bài thi hộ học sinh để tất cả đều đạt điểm tuyệt đối.","Cung cấp hệ thống gia sư ảo hỗ trợ giải đáp thắc mắc 24/7 và phân tích điểm mạnh, điểm yếu của từng người học.","Cắt giảm hoàn toàn vai trò của giáo viên trong nhà trường.","Tự động nâng điểm số định kỳ cho học sinh trên hệ thống sổ điểm điện tử."]'::jsonb, 1, 'AI đóng vai trò như một trợ giảng/gia sư thông minh, hỗ trợ học sinh tự học mọi lúc mọi nơi và cá nhân hóa trải nghiệm học tập.', 33) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_034', 'tinhoc', '2', 'mc', 'Trong ngành nông nghiệp thông minh, AI kết hợp với máy bay không người lái (drone) mang lại lợi ích chủ yếu nào?', '["Tự động làm thay đổi khí hậu thời tiết của cả vùng canh tác.","Chụp ảnh quang phổ phân tích sức khỏe cây trồng, phát hiện sớm sâu bệnh và phun thuốc trừ sâu cục bộ chính xác.","Thay thế hoàn toàn đất trồng trọt bằng vi mạch điện tử.","Làm cho cây trồng sinh trưởng và cho thu hoạch chỉ sau vài giờ."]'::jsonb, 1, 'Drone kết hợp AI phân tích ảnh đa phổ giúp phát hiện sớm sâu bệnh cục bộ để phun thuốc chính xác, tiết kiệm chi phí và bảo vệ môi trường.', 34) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_035', 'tinhoc', '2', 'mc', 'Công nghệ Deepfake dựa trên nền tảng AI gây ra mối lo ngại sâu sắc nhất trong đời sống xã hội về phương diện nào?', '["Tiêu tốn nhiều dung lượng ổ đĩa cứng khi lưu trữ video độ phân giải 4K.","Tạo ra video, hình ảnh hoặc giọng nói giả mạo người thật y như thật để lừa đảo, bôi nhọ danh dự hoặc thao túng tin tức.","Làm chậm tốc độ kết nối của mạng Wi-Fi gia đình.","Khiến các chương trình chỉnh sửa video truyền thống không thể cài đặt được trên máy tính."]'::jsonb, 1, 'Deepfake gây nguy cơ lớn khi bị lợi dụng để tạo video/âm thanh giả mạo tinh vi nhằm lừa đảo tài chính hoặc lan truyền tin giả bôi nhọ uy tín người khác.', 35) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_036', 'tinhoc', '2', 'mc', 'Trong lĩnh vực tài chính – ngân hàng, hệ thống AI đóng vai trò thiết yếu trong việc:', '["Tự động in thêm tiền mặt khi quỹ ngân hàng sắp cạn kiệt.","Phát hiện các giao dịch gian lận thẻ tín dụng theo thời gian thực dựa trên các bất thường về thói quen chi tiêu.","Cho phép tất cả khách hàng vay tiền mà không cần bất kỳ điều kiện thẩm định nào.","Xóa bỏ hoàn toàn mã pin và mật khẩu tài khoản của người dùng."]'::jsonb, 1, 'Hệ thống AI theo dõi các giao dịch ngân hàng theo thời gian thực để phát hiện ngay các dấu hiệu gian lận bất thường (như địa điểm chi tiêu lạ, số tiền đột biến).', 36) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_037', 'tinhoc', '2', 'mc', 'Một bác sĩ nhận được gợi ý chẩn đoán từ một phần mềm AI chẩn đoán bệnh da liễu với độ tin cậy được hệ thống thông báo là 96%. Hành động chuyên môn chuẩn mực nhất của bác sĩ là gì?', '["Kê đơn ngay lập tức theo đúng gợi ý của AI vì máy tính luôn chính xác hơn con người.","Sử dụng kết quả của AI như một nguồn tham khảo chuyên môn, kết hợp thăm khám lâm sàng, tiền sử bệnh nhân và xét nghiệm trước khi đưa ra kết luận chẩn đoán cuối cùng.","Bỏ qua hoàn toàn kết quả AI và không bao giờ sử dụng lại phần mềm y tế.","Chuyển hồ sơ bệnh án cho lập trình viên phần mềm để họ chịu trách nhiệm chẩn đoán."]'::jsonb, 1, 'AI chỉ đóng vai trò tham khảo và hỗ trợ; bác sĩ luôn là người chịu trách nhiệm chuyên môn và pháp lý cuối cùng đối với sức khỏe bệnh nhân.', 37) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_038', 'tinhoc', '2', 'mc', 'Vấn đề ''Hộp đen'' (Black Box) trong các mô hình AI học sâu (Deep Learning) đề cập đến thách thức nào?', '["Vỏ ngoài của các máy chủ chứa mô hình AI luôn được sơn màu đen để chống bức xạ.","Rất khó để con người giải thích tường tận từng bước suy luận logic bên trong mạng nơ-ron phức tạp dẫn đến kết quả đầu ra.","Máy tính không cho phép sao lưu dữ liệu ra bên ngoài thiết bị lưu trữ.","Mô hình AI chỉ hoạt động được vào ban đêm hoặc trong phòng tối."]'::jsonb, 1, 'Tính ''Hộp đen'' thể hiện thách thức trong việc giải thích tường minh cơ chế ra quyết định của các mô hình học sâu có hàng tỷ tham số nơ-ron.', 38) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_039', 'tinhoc', '2', 'mc', 'Trong nghiên cứu thiên văn học, các nhà khoa học đã sử dụng AI như thế nào để khám phá vũ trụ?', '["Điều khiển tên lửa vũ trụ bay nhanh hơn tốc độ ánh sáng.","Xử lí và sàng lọc hàng petabyte dữ liệu hình ảnh từ kính viễn vọng không gian để tìm kiếm các ngoại hành tinh và chuẩn tinh mờ nhạt.","Thay thế các trạm phát sóng vô tuyến trên mặt đất bằng phần mềm chatbot.","Tự động vẽ bản đồ bề mặt các ngôi sao ở thiên hà khác mà không cần quan sát dữ liệu."]'::jsonb, 1, 'AI tự động phân tích khối lượng dữ liệu khổng lồ từ các kính viễn vọng vũ trụ để phát hiện ngoại hành tinh mà các nhà khoa học khó lọc thủ công xuể.', 39) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_040', 'tinhoc', '2', 'mc', 'Một trang tin tức sử dụng AI để tự động tạo ra hàng nghìn bài báo mỗi ngày dựa trên việc quét tin từ các nguồn khác nhau. Vấn đề pháp lý và đạo đức lớn nhất đặt ra ở đây là gì?', '["Tiền điện chi trả cho hệ thống máy chủ quá tốn kém.","Nguy cơ vi phạm bản quyền tác giả gốc, lan truyền tin giả (fake news) chưa được kiểm chứng và thiếu trách nhiệm giải trình của biên tập viên.","Trình duyệt web của độc giả sẽ bị đóng băng khi mở bài viết.","Định dạng phông chữ trên bài báo không tương thích với điện thoại di động."]'::jsonb, 1, 'Tạo tin tức tự động quy mô lớn tiềm ẩn nguy cơ vi phạm quyền tác giả, thông tin sai lệch thiếu kiểm chứng và thiếu trách nhiệm giải trình.', 40) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_041', 'tinhoc', '2', 'mc', 'Hệ thống giao thông đô thị thông minh tại một thành phố lớn ứng dụng AI để điều khiển đèn tín hiệu giao thông. Giải pháp AI nào sau đây mang lại hiệu quả giảm ùn tắc tốt nhất?', '["Cố định thời gian đèn đỏ là 60 giây và đèn xanh là 30 giây ở mọi ngã tư suốt 24 giờ.","Phân tích luồng phương tiện trực tiếp qua hệ thống camera ở các hướng ngã tư, từ đó tự động điều chỉnh linh hoạt chu kỳ đèn xanh – đèn đỏ phù hợp với lưu lượng xe thực tế.","Tắt toàn bộ hệ thống đèn tín hiệu và để người tham gia giao thông tự điều tiết.","Chỉ bật đèn xanh cho làn đường có xe buýt lưu thông."]'::jsonb, 1, 'Đèn tín hiệu thông minh thích ứng theo lưu lượng phương tiện thời gian thực giúp giải phóng luồng xe đông, giảm thời gian chờ đợi và ùn tắc.', 41) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_042', 'tinhoc', '2', 'mc', 'Một công ty thương mại điện tử sử dụng AI để phân tích lịch sử duyệt web của khách hàng và tự động tăng giá sản phẩm đối với những khách hàng có vẻ đang rất cần gấp món hàng đó. Hành vi này phản ánh vấn đề gì trong ứng dụng AI?', '["Tối ưu hóa chuỗi cung ứng hàng hóa vượt trội.","Vấn đề đạo đức kinh doanh và thao túng giá thiếu minh bạch đối với người tiêu dùng.","Ứng dụng xuất sắc của AI trong việc bảo vệ dữ liệu khách hàng.","Lỗi kỹ thuật tràn bộ nhớ đệm trong cơ sở dữ liệu bán lẻ."]'::jsonb, 1, 'Sử dụng AI để định giá bất bình đẳng và thao túng người tiêu dùng vi phạm đạo đức kinh doanh và tính minh bạch thị trường.', 42) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_043', 'tinhoc', '2', 'mc', 'Trong quy trình sản xuất công nghiệp ô tô, cánh tay robot tích hợp thị giác máy tính AI được dùng để kiểm tra lỗi sơn trên bề mặt vỏ xe. Ưu thế rõ rệt của giải pháp này so với công nhân kiểm tra thủ công là:', '["Robot biết đàm phán giảm giá nguyên vật liệu với nhà cung ứng.","Tốc độ quét cực nhanh, hoạt động liên tục 24/7 với độ ổn định cao, không bị mệt mỏi hay phân tâm bởi các yếu tố tâm lý.","Robot có thể tự sơn lại toàn bộ chiếc xe theo màu sắc ngẫu nhiên tự chọn.","Không cần kiểm tra định kỳ hay bảo dưỡng phần cứng."]'::jsonb, 1, 'Robot kiểm tra chất lượng hoạt động liên tục không mệt mỏi với độ chính xác cao và nhất quán, loại bỏ sai sót do mỏi mắt của con người.', 43) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_044', 'tinhoc', '2', 'mc', 'Một trường học muốn áp dụng hệ thống điểm danh nhận diện khuôn mặt bằng AI tại cổng trường. Để bảo đảm quyền riêng tư của học sinh theo quy định đạo đức dữ liệu, nhà trường cần làm gì trước tiên?', '["Tự ý chia sẻ toàn bộ ảnh chân dung của học sinh lên mạng xã hội công khai.","Thu thập dữ liệu hình ảnh khi có sự đồng ý của phụ huynh/học sinh, cam kết bảo mật cơ sở dữ liệu và chỉ phục vụ mục đích quản lý điểm danh nội bộ.","Bán dữ liệu khuôn mặt cho các công ty quảng cáo để có kinh phí mua thêm máy ảnh.","Xóa bỏ toàn bộ nội quy nhà trường sau khi lắp đặt camera AI."]'::jsonb, 1, 'Bảo vệ quyền riêng tư yêu cầu sự đồng thuận của chủ thể dữ liệu, bảo mật cơ sở dữ liệu và chỉ sử dụng đúng mục đích giáo dục đã cam kết.', 44) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_045', 'tinhoc', '2', 'mc', 'Trong việc dự báo thời tiết và biến đổi khí hậu, các mô hình AI hiện đại như GraphCast (Google DeepMind) đã đem lại bước đột phá gì?', '["Ngăn chặn hoàn toàn các cơn bão không đổ bộ vào đất liền.","Dự báo quỹ đạo bão và biến đổi áp suất khí quyển toàn cầu trong vài ngày tới với tốc độ tính toán tính bằng giây, nhanh hơn hàng nghìn lần so với các mô hình siêu máy tính mô phỏng thời tiết truyền thống.","Làm giảm nhiệt độ trung bình của Trái Đất xuống ngay lập tức.","Dự báo chính xác từng hạt mưa rơi xuống vị trí cụ thể sau một năm."]'::jsonb, 1, 'Mô hình AI dự báo khí tượng toàn cầu đưa ra kết quả tính toán chỉ trong vài chục giây với độ chính xác cao vượt trội so với các siêu máy tính truyền thống.', 45) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_046', 'tinhoc', '2', 'mc', 'Khi một bức ảnh cá nhân của một nữ sinh bị kẻ xấu dùng công cụ AI cắt ghép khuôn mặt vào một video nhạy cảm (Deepfake) và phát tán lên mạng xã hội, hành vi này:', '["Chỉ là trò đùa vô hại của công nghệ số, không vi phạm pháp luật.","Vi phạm nghiêm trọng pháp luật (xúc phạm danh dự, nhân phẩm, làm nhục người khác) và xâm phạm đạo đức công nghệ nghiêm trọng.","Là một cách thử nghiệm tính sáng tạo của mô hình học sâu.","Do nhà phát triển mô hình AI chịu toàn bộ trách nhiệm hình sự thay cho người phát tán."]'::jsonb, 1, 'Cắt ghép khuôn mặt bôi nhọ người khác bằng Deepfake là hành vi vi phạm nghiêm trọng pháp luật về quyền nhân thân và danh dự của công dân.', 46) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_047', 'tinhoc', '2', 'mc', 'Một bệnh viện tuyến huyện vùng sâu vùng xa gặp tình trạng thiếu bác sĩ chuyên khoa mắt. Giải pháp ứng dụng AI nào sau đây là thiết thực và khả thi nhất để hỗ trợ người dân địa phương?', '["Mua một robot phẫu thuật đắt tiền thay thế toàn bộ y bác sĩ tại trạm xá.","Trang bị phần mềm AI chụp đáy mắt tự động tầm soát bệnh võng mạc tiểu đường, kết nối từ xa để cảnh báo các ca nguy cơ cao cần chuyển lên tuyến trên điều trị kịp thời.","Cho người bệnh tự tra cứu thuốc trên mạng xã hội mà không cần khám bệnh.","Dừng hoàn toàn việc khám mắt cho đến khi có bác sĩ chuyên khoa về công tác."]'::jsonb, 1, 'Phần mềm AI tầm soát bệnh mắt từ xa giúp y tế cơ sở phát hiện sớm các ca bệnh nặng để kịp thời chuyển tuyến điều trị, giảm tải cho tuyến trên.', 47) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_048', 'tinhoc', '2', 'mc', 'Hiện tượng ''bong bóng lọc'' (Filter Bubble) trên các nền tảng mạng xã hội do thuật toán gợi ý nội dung AI gây ra hệ lụy tiêu cực nào đối với người dùng?', '["Khiến màn hình điện thoại bị ám màu vàng sau thời gian dài sử dụng.","Người dùng chỉ tiếp cận những quan điểm, thông tin trùng với sở thích/định kiến cá nhân của mình, dẫn đến cái nhìn phiến diện và chia rẽ xã hội.","Tốc độ lướt mạng bị chậm lại do thuật toán mã hóa dữ liệu.","Tài khoản người dùng bị khóa vĩnh viễn sau 30 ngày."]'::jsonb, 1, 'Bong bóng lọc khiến người dùng chỉ nhìn thấy thông tin củng cố quan điểm cá nhân có sẵn, hạn chế góc nhìn đa chiều và làm gia tăng định kiến.', 48) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_049', 'tinhoc', '2', 'mc', 'Một kỹ sư phát triển phần mềm tuyển dụng nhân sự nhận thấy thuật toán AI tự động đánh rớt hồ sơ của các ứng viên nữ nộp vào vị trí lập trình viên, dù điểm số của họ rất cao. Biện pháp kỹ thuật nào sau đây là đúng đắn nhất để khắc phục?', '["Tắt hoàn toàn máy chủ tuyển dụng và tuyển dụng bằng bốc thăm may rủi.","Kiểm tra lại tập dữ liệu huấn luyện lịch sử, loại bỏ các thuộc tính định danh về giới tính và tái cân bằng mẫu dữ liệu để đảm bảo tính công bằng (Fairness).","Giữ nguyên thuật toán vì AI luôn đưa ra quyết định khách quan hơn con người.","Buộc tất cả ứng viên nữ phải đổi tên thành nam giới trong hồ sơ xin việc."]'::jsonb, 1, 'Cần chuẩn hóa lại tập dữ liệu huấn luyện, loại bỏ các đặc trưng gây thiên vị giới tính và tái cân bằng mẫu dữ liệu để đảm bảo tính công bằng (Fairness).', 49) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_050', 'tinhoc', '2', 'mc', 'Lợi ích lớn nhất của việc ứng dụng AI trong hệ thống lưới điện thông minh (Smart Grid) là gì?', '["Tự động dự báo nhu cầu tiêu thụ điện năng theo khung giờ và thời tiết, từ đó điều phối nguồn điện từ năng lượng tái tạo (gió, mặt trời) ổn định và giảm lãng phí.","Miễn phí hoàn toàn tiền điện hàng tháng cho tất cả các hộ gia đình.","Làm cho các thiết bị điện trong nhà không bao giờ bị chập cháy do sét đánh.","Thay thế toàn bộ dây dẫn điện bằng kết nối vô tuyến tầm ngắn."]'::jsonb, 0, 'Hệ thống lưới điện thông minh dùng AI dự báo cung cầu để tích hợp và điều phối tối ưu các nguồn năng lượng tái tạo không ổn định.', 50) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_051', 'tinhoc', '2', 'mc', 'Một công ty luật áp dụng trợ lý AI để tra cứu các án lệ và văn bản pháp luật. Nhân viên sử dụng AI cần lưu ý điều gì nhất để tránh rủi ro nghề nghiệp?', '["Phải kiểm tra lại số hiệu điều luật và nội dung trích dẫn từ nguồn công báo chính thức, vì AI có thể tạo ra các điều luật ''ảo'' không có thật trong thực tế.","Không được dùng chuột máy tính khi đang thao tác với AI.","Chỉ sử dụng AI khi kết nối bằng cổng mạng LAN có dây.","Phải nộp phí bản quyền cho từng chữ cái mà AI sinh ra."]'::jsonb, 0, 'Người làm luật phải luôn xác minh lại số hiệu văn bản từ công báo pháp luật chính thống vì AI có thể mắc lỗi ảo giác và trích dẫn điều luật không có thật.', 51) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_052', 'tinhoc', '2', 'mc', 'Trong lĩnh vực âm nhạc và nghệ thuật, AI tạo sinh (như Suno, Midjourney) đang tạo ra tranh cãi lớn nhất liên quan đến:', '["Định dạng tệp xuất ra là MP3 hay WAV, PNG hay JPEG.","Việc thu thập hàng tỷ tác phẩm của các nghệ sĩ con người để huấn luyện mô hình mà không xin phép hay trả tiền bản quyền tác giả.","Trọng lượng của máy tính khi cài đặt phần mềm vẽ tranh quá nặng.","Việc tranh vẽ bằng AI chỉ hiển thị được trên màn hình máy tính để bàn."]'::jsonb, 1, 'Tranh cãi gay gắt nhất là việc sử dụng các tác phẩm có bản quyền của nghệ sĩ làm dữ liệu huấn luyện cho AI mà không có sự đồng thuận hay chia sẻ lợi ích.', 52) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_053', 'tinhoc', '2', 'mc', 'Một viện bảo tàng áp dụng hệ thống thuyết minh viên ảo AI bằng giọng nói đa ngôn ngữ, tự động nhận diện hiện vật khi du khách đứng trước tủ trưng bày. Ưu điểm nổi bật của giải pháp này là:', '["Du khách được tự do mang hiện vật bảo tàng về nhà sau chuyến tham quan.","Cá nhân hóa trải nghiệm tham quan, cung cấp thông tin theo ngôn ngữ mẹ đẻ của du khách bất kỳ lúc nào mà không bị giới hạn số lượng hướng dẫn viên.","Thay thế toàn bộ các hiện vật cổ thật bằng hình ảnh hoạt họa 2D.","Không cần duy trì nguồn điện chiếu sáng trong phòng trưng bày."]'::jsonb, 1, 'Thuyết minh AI đa ngôn ngữ giúp du khách mọi quốc tịch tiếp cận tri thức văn hóa sống động và thuận tiện mà không phụ thuộc vào số lượng hướng dẫn viên.', 53) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_054', 'tinhoc', '2', 'mc', 'Ứng dụng AI phân tích cảm xúc (Sentiment Analysis) trên các bình luận mạng xã hội giúp các doanh nghiệp:', '["Biết được mật khẩu Facebook cá nhân của từng khách hàng.","Nắm bắt được mức độ hài lòng hoặc phản ứng tiêu cực của công chúng đối với sản phẩm/dịch vụ để kịp thời cải thiện.","Tự động xóa tài khoản ngân hàng của những người chê bai sản phẩm.","Ép buộc khách hàng phải mua sản phẩm mới ra mắt."]'::jsonb, 1, 'Phân tích cảm xúc văn bản tự động giúp doanh nghiệp lắng nghe phản hồi của người tiêu dùng để cải tiến sản phẩm và xử lí khủng hoảng kịp thời.', 54) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_055', 'tinhoc', '2', 'mc', 'Một nhà nghiên cứu hóa học sử dụng AI để tìm kiếm các hợp chất mới làm chất bán dẫn cho pin xe điện. AI đóng vai trò như thế nào trong tình huống này?', '["Trực tiếp đi khai thác quặng mỏ kim loại hiếm ở thực địa.","Sàng lọc ảo hàng triệu công thức phân tử trên máy tính trong vài giờ để chọn ra vài ứng viên tiềm năng nhất, tiết kiệm nhiều năm thí nghiệm trong phòng lab.","Tự động đăng ký bản quyền phát minh tại cơ quan nhà nước mà không cần con người.","Thay thế hoàn toàn quy trình thử nghiệm an toàn vật lý của pin."]'::jsonb, 1, 'AI hỗ trợ mô phỏng và sàng lọc ảo hàng triệu cấu trúc hóa học tiềm năng, rút ngắn đáng kể thời gian và chi phí thử nghiệm thực tế.', 55) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_056', 'tinhoc', '2', 'mc', 'Khái niệm ''Tính minh bạch và trách nhiệm giải trình'' (Transparency and Accountability) trong đạo đức AI đòi hỏi:', '["Mọi màn hình máy tính chạy AI đều phải làm bằng kính trong suốt.","Người dùng và tổ chức triển khai AI phải giải thích được nguyên lý vận hành cơ bản, mục đích sử dụng và phải có con người chịu trách nhiệm pháp lý khi hệ thống gây thiệt hại.","Tất cả mã nguồn của mọi tập đoàn công nghệ trên thế giới phải được xóa bỏ định kỳ.","AI phải tự động thanh toán các khoản tiền phạt vi phạm hành chính thay cho người sử dụng."]'::jsonb, 1, 'Trách nhiệm giải trình yêu cầu tổ chức phát triển/ứng dụng AI phải minh bạch về mục đích, cơ chế hoạt động và phải có con người chịu trách nhiệm trước pháp luật.', 56) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_057', 'tinhoc', '2', 'mc', 'Một chiếc xe tự lái cấp độ cao gặp tình huống khẩn cấp bất khả kháng trên đường hẹp: hoặc tiếp tục lao thẳng đâm vào dải phân cách gây nguy hiểm cho người ngồi trên xe, hoặc đánh lái sang phải đâm vào người đi bộ trên vỉa hè. Tình huống này là ví dụ kinh điển về:', '["Lỗi thiếu bộ nhớ RAM trong xử lí đồ họa của xe.","Tiến thoái lưỡng nan về mặt đạo đức (The Trolley Problem in AI) mà lập trình viên và xã hội phải đối mặt khi thiết kế thuật toán cho máy móc tự hành.","Sự suy giảm chất lượng của lốp xe ô tô theo thời gian.","Lỗi đứt cáp tín hiệu cảm biến lùi phía sau xe."]'::jsonb, 1, 'Tình huống này minh họa bài toán đạo đức ''Chiếc xe điện'' (Trolley Problem) khi lập trình AI tự hành phải đưa ra quyết định trong tình huống bất khả kháng.', 57) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_058', 'tinhoc', '2', 'mc', 'Để bảo vệ bản thân trước các cuộc gọi lừa đảo giả mạo giọng nói của người thân bằng công nghệ AI Voice Cloning, biện pháp phòng ngừa thực tế và hiệu quả nhất là gì?', '["Ngắt kết nối mạng Internet gia đình vĩnh viễn.","Bình tĩnh, không vội vàng chuyển tiền; cúp máy và gọi lại trực tiếp vào số điện thoại thường dùng của người thân hoặc đặt ra các câu hỏi/mật khẩu quy ước riêng mà chỉ người trong gia đình mới biết để xác minh.","Chuyển ngay số tiền nhỏ theo yêu cầu để kiểm tra tài khoản.","Đập vỡ điện thoại thông minh để tránh bị lây nhiễm mã độc qua sóng âm thanh."]'::jsonb, 1, 'Biện pháp phòng ngừa thông minh là luôn bình tĩnh xác minh qua kênh liên lạc độc lập hoặc đặt câu hỏi quy ước riêng để chống lừa đảo bằng giọng nói giả mạo AI.', 58) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_059', 'tinhoc', '2', 'mc', 'Một giáo viên sử dụng phần mềm AI để hỗ trợ chấm các bài thi tự luận môn Ngữ văn của học sinh. Cách tiếp cận sư phạm chuẩn mực và nhân văn nhất là:', '["Lấy điểm số AI chấm làm điểm chính thức tuyệt đối mà không cần đọc lại bài của học sinh.","Sử dụng AI để phát hiện các lỗi chính tả, ngữ pháp hoặc đạo văn, sau đó giáo viên trực tiếp đọc, cảm nhận mạch cảm xúc, tư duy của học sinh và quyết định điểm số cuối cùng kèm nhận xét cụ thể.","Yêu cầu học sinh viết bài thi dưới dạng mã nhị phân để AI chấm dễ hơn.","Giao toàn bộ việc giảng dạy trên lớp cho robot thuyết trình."]'::jsonb, 1, 'Giáo viên sử dụng AI như công cụ lọc lỗi kỹ thuật, nhưng trực tiếp đọc và cảm nhận bài văn để đánh giá tư duy và khích lệ học sinh một cách nhân văn.', 59) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_060', 'tinhoc', '2', 'mc', 'Trước nguy cơ AI tự động hóa có thể thay thế một số công việc thủ công, lặp đi lặp lại trong tương lai, hành động chủ động và đúng đắn nhất của học sinh hiện nay là:', '["Bỏ học để đi làm các công việc lao động chân tay giản đơn ngay từ bây giờ.","Không ngừng học hỏi, rèn luyện tư duy phản biện, kỹ năng giải quyết vấn đề phức tạp, năng lực sáng tạo và khả năng thích ứng linh hoạt với các công cụ công nghệ mới.","Kêu gọi phá hủy mọi trung tâm dữ liệu máy chủ trên toàn cầu.","Tuyệt đối không học bất cứ kiến thức nào liên quan đến máy tính và công nghệ thông tin."]'::jsonb, 1, 'Học sinh cần chủ động rèn luyện tư duy phản biện, năng lực giải quyết vấn đề phức tạp, sáng tạo và thích ứng để phát triển cùng công nghệ AI.', 60) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_061', 'tinhoc', '3', 'mc', 'Thiết bị mạng nào hoạt động như một bộ tập trung tín hiệu, khi nhận được dữ liệu từ một cổng thì phát tán (broadcast) tín hiệu đó ra tất cả các cổng còn lại mà không kiểm tra địa chỉ đích?', '["Switch (Bộ chuyển mạch).","Hub (Bộ chia mạng).","Router (Bộ định tuyến).","Modem (Bộ điều giải)."]'::jsonb, 1, 'Hub nhận dữ liệu từ một cổng và gửi phát tán (broadcast) tín hiệu điện đến tất cả các cổng còn lại trên thiết bị.', 61) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_062', 'tinhoc', '3', 'mc', 'Thiết bị mạng có chức năng chuyển đổi qua lại giữa tín hiệu tương tự (analog) truyền trên đường dây của nhà cung cấp dịch vụ viễn thông và tín hiệu số (digital) của mạng máy tính là:', '["Switch.","WAP (Wireless Access Point).","Modem.","Hub."]'::jsonb, 2, 'Modem (Modulator / Demodulator) có nhiệm vụ điều chế và giải điều chế tín hiệu giữa tương tự và số.', 62) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_063', 'tinhoc', '3', 'mc', 'Thiết bị mạng nào hoạt động thông minh hơn Hub nhờ khả năng đọc và lưu bảng địa chỉ MAC, từ đó chỉ chuyển tiếp khung dữ liệu (frame) chính xác đến cổng kết nối với máy tính đích?', '["Switch (Bộ chuyển mạch).","Bộ lặp tín hiệu (Repeater).","Cáp xoắn đôi RJ45.","Đầu nối BNC."]'::jsonb, 0, 'Switch lưu bảng địa chỉ MAC và chỉ chuyển tiếp khung tin đến đúng cổng gắn với máy nhận, giúp tối ưu băng thông.', 63) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_064', 'tinhoc', '3', 'mc', 'Thiết bị mạng nào có chức năng chính là kết nối các mạng máy tính khác nhau (ví dụ: kết nối mạng LAN gia đình với mạng diện rộng Internet) và tìm đường đi tối ưu cho các gói tin dựa trên địa chỉ IP?', '["Hub.","Switch tầng 2.","Router (Bộ định tuyến).","Cáp mạng quang."]'::jsonb, 2, 'Router hoạt động ở tầng mạng, định tuyến các gói tin giữa các mạng khác nhau dựa trên địa chỉ IP.', 64) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_065', 'tinhoc', '3', 'mc', 'Thiết bị WAP (Wireless Access Point - Điểm truy cập không dây) có vai trò chủ yếu nào trong hệ thống mạng?', '["Chuyển đổi tín hiệu quang thành tín hiệu điện thoại cố định.","Thu phát sóng vô tuyến (Wi-Fi) để cho phép các thiết bị di động kết nối vào mạng LAN có dây.","Thay thế hoàn toàn chức năng cấp phát địa chỉ IP công cộng của nhà cung cấp mạng ISP.","Ngăn chặn tuyệt đối mọi loại virus máy tính xâm nhập vào mạng nội bộ."]'::jsonb, 1, 'WAP đóng vai trò như cầu nối không dây, cho phép các thiết bị Wi-Fi gia nhập vào hệ thống mạng LAN có dây.', 65) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_066', 'tinhoc', '3', 'mc', 'Đầu cắm chuẩn thường được sử dụng phổ biến nhất trên cáp xoắn đôi (UTP/STP) để cắm vào card mạng của máy tính hoặc cổng trên Switch/Router là:', '["Chuẩn USB Type-C.","Chuẩn RJ45.","Chuẩn HDMI.","Chuẩn VGA."]'::jsonb, 1, 'Chuẩn RJ45 (Registered Jack 45) là đầu bấm tiêu chuẩn cho cáp xoắn đôi dùng trong mạng Ethernet máy tính.', 66) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_067', 'tinhoc', '3', 'mc', 'Tại sao trong các hệ thống mạng LAN hiện đại, người ta hầu như đã thay thế hoàn toàn thiết bị Hub bằng Switch?', '["Vì Hub tiêu tốn điện năng gấp 10 lần so với Switch.","Vì Hub gây ra xung đột dữ liệu (collision) trên toàn mạng, làm nghẽn băng thông khi nhiều máy cùng gửi dữ liệu, còn Switch tạo ra các kênh truyền riêng biệt giữa các cổng.","Vì Hub không thể cắm vừa đầu cáp mạng chuẩn RJ45.","Vì Hub chỉ kết nối được tối đa 2 máy tính cùng lúc."]'::jsonb, 1, 'Hub chia sẻ miền xung đột chung dẫn đến va chạm gói tin khi nhiều máy cùng gửi; Switch tạo kênh truyền riêng biệt (micro-segmentation) giữa từng cổng.', 67) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_068', 'tinhoc', '3', 'mc', 'Phát biểu nào sau đây phân biệt chính xác nhất bản chất giữa Router và Switch trong mô hình mạng trường học?', '["Switch kết nối các máy tính trong cùng một mạng LAN nội bộ dựa vào địa chỉ MAC; Router định tuyến dữ liệu giữa các mạng LAN khác nhau hoặc giữa mạng LAN với Internet dựa vào địa chỉ IP.","Switch dùng để phát Wi-Fi, còn Router chỉ dùng để cắm dây mạng.","Router xử lí dữ liệu nhanh hơn Switch ở cấp độ mạng nội bộ.","Switch kết nối qua sóng vệ tinh, còn Router kết nối qua cáp đồng."]'::jsonb, 0, 'Switch liên kết các thiết bị trong cùng một mạng LAN bằng địa chỉ MAC; Router định tuyến luồng dữ liệu giữa các mạng khác nhau bằng địa chỉ IP.', 68) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_069', 'tinhoc', '3', 'mc', 'Thiết bị ''Wi-Fi Router'' mà các hộ gia đình thường được nhà mạng (Viettel, VNPT, FPT,...) trang bị thực chất là thiết bị tích hợp những thành phần mạng nào sau đây?', '["Chỉ thuần túy là một cổng cắm dây điện nguồn.","Tích hợp Modem (quang), Router, Switch (các cổng LAN) và Điểm truy cập không dây (WAP).","Chỉ duy nhất một con chip Hub cổ điển.","Một máy chủ siêu máy tính thu nhỏ có màn hình cảm ứng."]'::jsonb, 1, 'Wi-Fi Router gia đình là thiết bị tích hợp ''tất cả trong một'' gồm Modem quang ONT, Router định tuyến, Switch 4 cổng và bộ phát Wi-Fi (WAP).', 69) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_070', 'tinhoc', '3', 'mc', 'Khi máy tính A gửi dữ liệu cho máy tính B trong cùng một mạng LAN kết nối qua Switch. Máy tính C (cũng cắm vào Switch đó) có đọc trộm được luồng dữ liệu này bằng phần mềm bắt gói tin thông thường không? Vì sao?', '["Có, vì Switch gửi dữ liệu đến tất cả các máy trong mạng giống hệt như Hub.","Không (trong điều kiện hoạt động chuẩn), vì Switch chỉ chuyển tiếp gói tin đến đúng cổng vật lý kết nối với máy tính B dựa vào bảng MAC.","Có, vì mọi thiết bị cắm chung một phòng học đều nhận chung tín hiệu điện áp.","Có, vì máy tính C có cùng địa chỉ IP với máy tính B."]'::jsonb, 1, 'Switch chuyển tiếp khung tin thẳng tới cổng gắn máy B, nên máy C trên cổng khác không nhận được tín hiệu điện của khung tin đó.', 70) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_071', 'tinhoc', '3', 'mc', 'Một gia đình lắp mạng Internet cáp quang. Đường cáp quang từ bên ngoài kéo vào nhà sẽ cắm trực tiếp vào cổng nào của thiết bị mạng gia đình?', '["Cổng quang (thường ký hiệu PON/Optical) trên Modem quang (ONT).","Cổng USB 2.0 trên máy in gia đình.","Cổng âm thanh 3.5mm trên máy vi tính.","Cổng xuất hình ảnh HDMI trên tivi thông minh."]'::jsonb, 0, 'Dây quang truyền ánh sáng được cắm vào cổng PON/Optical của Modem quang để biến đổi quang - điện.', 71) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_072', 'tinhoc', '3', 'mc', 'Một nhân viên kỹ thuật nhìn vào mặt sau của một chiếc Router văn phòng thấy có 1 cổng ghi nhãn WAN (thường màu vàng hoặc xanh biển) và 4 cổng ghi nhãn LAN (1, 2, 3, 4). Cổng WAN dùng để:', '["Cắm chuột và bàn phím máy tính điều khiển Router.","Kết nối với Modem của nhà cung cấp dịch vụ mạng (Internet) hoặc mạng cấp trên.","Cắm tai nghe để nghe tín hiệu mạng.","Nối dây sang một máy in văn phòng dùng chung."]'::jsonb, 1, 'Cổng WAN (Wide Area Network) dùng để nối ra mạng diện rộng bên ngoài hoặc Modem của nhà cung cấp mạng ISP.', 72) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_073', 'tinhoc', '3', 'mc', 'Sự khác biệt cơ bản giữa mạng LAN có dây (dùng cáp xoắn đôi qua Switch) và mạng không dây WLAN (dùng WAP) về mặt môi trường truyền dẫn là:', '["Mạng có dây truyền tín hiệu điện/quang qua dây dẫn vật lý cố định; mạng không dây truyền dữ liệu bằng sóng điện từ (vô tuyến) lan tỏa trong không gian.","Mạng có dây không cần địa chỉ IP, mạng không dây bắt buộc phải có địa chỉ IP.","Mạng không dây luôn đạt tốc độ truyền tải cao gấp 100 lần mạng có dây trong mọi điều kiện.","Mạng có dây không bao giờ bị hỏng hóc hay suy hao tín hiệu theo khoảng cách."]'::jsonb, 0, 'Môi trường truyền dẫn: có dây dùng cáp đồng/quang hữu tuyến; không dây dùng sóng vô tuyến điện từ lan truyền trong không gian.', 73) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_074', 'tinhoc', '3', 'mc', 'Phòng thực hành Tin học của trường có 40 máy tính để bàn đặt cố định sát nhau. Giải pháp kết nối mạng tối ưu, ổn định và tiết kiệm nhất cho phòng máy này là:', '["Mua 40 chiếc USB Wi-Fi cắm vào từng máy để bắt sóng từ một cục phát di động 4G.","Sử dụng các Switch 24 cổng kết nối mạng LAN có dây bằng cáp xoắn đôi Cat6 đến từng máy tính.","Nối dây trực tiếp từ cổng mạng của máy tính số 1 sang máy tính số 2, nối tiếp dần đến máy số 40.","Dùng 40 bộ phát sóng vệ tinh độc lập cho từng máy tính."]'::jsonb, 1, 'Đối với các máy để bàn cố định số lượng lớn, dùng Switch kết hợp cáp mạng xoắn đôi Cat6 cho băng thông cao, độ trễ thấp và độ ổn định cao nhất.', 74) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_075', 'tinhoc', '3', 'mc', 'Quán cà phê có diện tích rộng 3 tầng lầu, lượng khách sử dụng điện thoại thông minh cùng lúc lên tới 150 người. Khách ở tầng 2 và tầng 3 phàn nàn sóng Wi-Fi rất chập chờn. Giải pháp thiết kế mạng phù hợp nhất là:', '["Mua thêm một chiếc Hub cắm ở chân cầu thang tầng 1.","Kéo dây cáp mạng LAN từ Router chính tại tầng 1 lên tầng 2 và tầng 3, lắp thêm các thiết bị WAP (hoặc hệ thống Wi-Fi Mesh chuyên dụng) ở các tầng để mở rộng vùng phủ sóng.","Yêu cầu toàn bộ khách hàng cắm dây cáp mạng vào điện thoại thông minh để dùng mạng có dây.","Tắt nguồn điện của quán cà phê rồi bật lại mỗi 15 phút."]'::jsonb, 1, 'Lắp thêm các WAP ở từng tầng kết nối qua cáp mạng LAN tới Router trung tâm là giải pháp chuẩn mực để mở rộng vùng phủ sóng không dây.', 75) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_076', 'tinhoc', '3', 'mc', 'Bảng địa chỉ MAC (MAC Address Table) được lưu trữ bên trong bộ nhớ của thiết bị nào sau đây?', '["Hub.","Cáp mạng quang.","Switch.","Ổ đĩa cứng HDD."]'::jsonb, 2, 'Switch là thiết bị quản lý và lưu trữ bảng địa chỉ MAC tương ứng với các cổng vật lý của nó.', 76) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_077', 'tinhoc', '3', 'mc', 'Khi một Switch mới được bật nguồn lần đầu, bảng địa chỉ MAC của nó đang hoàn toàn trống. Nếu máy A gửi một gói tin cho máy B, Switch sẽ xử lí như thế nào?', '["Từ chối truyền dữ liệu và báo lỗi ngay lập tức.","Học địa chỉ MAC của máy A gán với cổng nhận, sau đó thực hiện ''ngập lụt'' (flooding - gửi gói tin ra tất cả các cổng còn lại) để tìm máy B.","Tự động xóa gói tin của máy A khỏi bộ nhớ đệm.","Tắt nguồn thiết bị Switch để bảo vệ an toàn mạng."]'::jsonb, 1, 'Khi chưa biết máy B ở cổng nào, Switch học MAC máy A và thực hiện flooding (gửi ra tất cả các cổng khác) để tìm máy đích.', 77) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_078', 'tinhoc', '3', 'mc', 'Địa chỉ MAC (Media Access Control) là:', '["Địa chỉ logic có thể thay đổi linh hoạt do nhà mạng ISP cấp mỗi khi kết nối Internet.","Tên trang web do người dùng đăng ký trên hệ thống máy chủ tên miền.","Địa chỉ vật lý duy nhất gồm 48 bit (6 byte) được nhà sản xuất ghi cố định vào chip nhớ của card mạng (NIC).","Mật khẩu bảo vệ mạng Wi-Fi gia đình."]'::jsonb, 2, 'Địa chỉ MAC gồm 48 bit (6 byte) được nhà sản xuất ghi cố định vào card mạng, là địa chỉ vật lý duy nhất trên thế giới.', 78) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_079', 'tinhoc', '3', 'mc', 'Một học sinh cắm dây mạng từ máy tính của mình vào cổng số 1 của Switch, cắm máy in mạng vào cổng số 2 của Switch đó. Cả hai thiết bị đều chưa kết nối với Internet hay Router nào khác. Hai thiết bị này:', '["Hoàn toàn không thể giao tiếp được với nhau vì bắt buộc phải có Internet thì mạng mới chạy được.","Có thể giao tiếp và in ấn được trong mạng nội bộ LAN nếu cả hai được thiết lập địa chỉ IP cùng một dải mạng phù hợp.","Bị chập cháy nguồn điện do thiếu thiết bị điều hòa điện áp.","Tự động kết nối với mạng vệ tinh quốc tế."]'::jsonb, 1, 'Mạng LAN nội bộ qua Switch có thể hoạt động truyền tệp/in ấn bình thường mà không cần có Internet, miễn là các thiết bị cùng dải IP mạng.', 79) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_080', 'tinhoc', '3', 'mc', 'Thiết bị nào sau đây có khả năng ngăn chặn các broadcast storm (bão phát tán tín hiệu) không lan truyền sang các mạng khác?', '["Hub.","Switch thông thường (Layer 2 không chia VLAN).","Router.","Đầu chia tín hiệu chữ T."]'::jsonb, 2, 'Router hoạt động ở tầng mạng và theo mặc định sẽ không chuyển tiếp các gói tin broadcast sang mạng khác, giúp cô lập miền quảng bá.', 80) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_081', 'tinhoc', '3', 'mc', 'Một văn phòng có 1 Router chính kết nối Internet và 1 Switch 16 cổng. Nhân viên vô tình cắm 2 đầu của cùng một sợi dây cáp mạng vào 2 cổng trên cùng chiếc Switch đó (tạo thành vòng lặp mạng - loop) mà Switch không có tính năng chống lặp (STP). Hiện tượng gì sẽ xảy ra?', '["Mạng hoạt động nhanh hơn gấp đôi nhờ có 2 đường truyền.","Xảy ra hiện tượng ''bão quảng bá'' (broadcast storm), đèn cổng mạng nhấp nháy liên tục, mạng bị tê liệt hoàn toàn và mất kết nối.","Dây cáp mạng bị nổ tung do xung đột điện thế.","Router tự động chuyển đổi thành siêu máy tính."]'::jsonb, 1, 'Vòng lặp mạng (Loop) trên Switch không có giao thức chống lặp STP sẽ sinh ra bão quảng bá (broadcast storm) làm cạn kiệt tài nguyên và sập mạng.', 81) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_082', 'tinhoc', '3', 'mc', 'Trong thông số kỹ thuật của một cổng mạng trên Switch có ghi: ''10/100/1000 Mbps''. Thông số này có ý nghĩa gì?', '["Cổng mạng đó có thể kết nối được cùng lúc 1000 máy vi tính.","Cổng mạng có khả năng tự động đàm phán và hoạt động ở các tốc độ truyền dữ liệu tối đa là 10 Mbps, 100 Mbps hoặc 1000 Mbps (1 Gbps) tùy thuộc vào thiết bị cắm vào.","Cổng mạng tiêu thụ công suất điện tối đa 1000 Watts.","Cáp mạng cắm vào cổng này không được dài quá 10 mét."]'::jsonb, 1, 'Ký hiệu 10/100/1000 Mbps chỉ khả năng tự tương thích của cổng ở 3 tốc độ chuẩn Ethernet, Fast Ethernet và Gigabit Ethernet.', 82) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_083', 'tinhoc', '3', 'mc', 'Băng tần kép (Dual-Band) thường thấy trên các thiết bị phát Wi-Fi (WAP/Router) hiện nay hỗ trợ phát sóng ở hai tần số vô tuyến nào?', '["1.2 GHz và 3.6 GHz.","2.4 GHz và 5 GHz.","100 MHz và 200 MHz.","900 MHz và 1800 MHz."]'::jsonb, 1, 'Chuẩn Wi-Fi băng tần kép phát sóng đồng thời ở hai tần số vô tuyến 2.4 GHz và 5 GHz.', 83) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_084', 'tinhoc', '3', 'mc', 'Ưu điểm vượt trội của băng tần Wi-Fi 5 GHz so với băng tần 2.4 GHz là gì?', '["Tốc độ truyền dữ liệu cao hơn nhiều, ít bị nhiễu sóng từ các thiết bị gia dụng (như lò vi sóng, bluetooth), nhưng khả năng xuyên tường và tầm phủ sóng hẹp hơn.","Khả năng truyền sóng xuyên qua các bức tường bê tông dày tốt hơn nhiều lần.","Khoảng cách phủ sóng xa hơn 5 km mà không suy hao.","Không cần mật khẩu khi đăng nhập kết nối."]'::jsonb, 0, 'Sóng 5 GHz có băng thông lớn hơn, truyền nhanh hơn và ít nhiễu, nhưng suy hao nhanh hơn khi gặp vật cản/tường bê tông.', 84) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_085', 'tinhoc', '3', 'mc', 'Một kỹ sư mạng muốn thiết lập kết nối giữa mạng LAN của trường THPT số 1 và mạng LAN của trường THPT số 2 cách nhau 5 km qua đường truyền viễn thông công cộng. Thiết bị bắt buộc phải có ở biên giới của mỗi trường để định tuyến luồng dữ liệu là:', '["Bộ chia Hub 8 cổng.","Bộ chuyển mạch Switch không quản lý.","Router (Bộ định tuyến).","Cáp xoắn đôi Cat5e loại không vỏ bọc."]'::jsonb, 2, 'Liên kết hai mạng LAN khác nhau qua mạng diện rộng bắt buộc phải thông qua Router ở mỗi đầu mạng để định tuyến gói tin.', 85) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_086', 'tinhoc', '3', 'mc', 'Tại sao một chiếc máy tính xách tay dù bắt được sóng Wi-Fi rất căng từ WAP nhưng vẫn hiện biểu tượng quả địa cầu có dấu chấm than và ghi dòng chữ ''No Internet Access''?', '["Do chiếc máy tính đó bị hỏng màn hình hiển thị.","Kết nối không dây từ laptop tới WAP hoạt động tốt, nhưng từ Router chính ra mạng Internet bên ngoài (nhà mạng ISP) đang bị gián đoạn hoặc Router lỗi cấp phát địa chỉ IP/DNS.","Do sóng Wi-Fi 5GHz làm hỏng card mạng của máy tính.","Do dây nguồn của laptop chưa cắm vào ổ điện 220V."]'::jsonb, 1, 'Sóng Wi-Fi mạnh chỉ chứng tỏ kết nối vô tuyến tới WAP tốt; nếu đường truyền từ Router ra ngoài nhà mạng ISP bị đứt, máy sẽ không vào được Internet.', 86) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_087', 'tinhoc', '3', 'mc', 'Khoảng cách truyền dẫn tối đa theo tiêu chuẩn của một đoạn cáp mạng xoắn đôi đồng (Cat5e/Cat6) nối từ Switch đến máy tính mà không cần thiết bị lặp/khuếch đại là khoảng bao nhiêu?', '["10 mét.","100 mét.","1000 mét (1 km).","5000 mét (5 km)."]'::jsonb, 1, 'Tiêu chuẩn Ethernet quy định khoảng cách tối đa cho một đoạn cáp đồng xoắn đôi UTP là 100 mét để đảm bảo suy hao tín hiệu trong giới hạn cho phép.', 87) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_088', 'tinhoc', '3', 'mc', 'Một thư viện lắp đặt mạng gồm: 1 đường truyền cáp quang của ISP, 1 Modem quang, 1 Router, 2 Switch 24 cổng và 4 thiết bị WAP. Sơ đồ kết nối phân tầng chuẩn xác nhất từ ngoài vào trong là:', '["Đường truyền ISP -> Modem -> Router -> Switch -> (Các máy tính để bàn & các bộ WAP phát cho thiết bị di động).","Đường truyền ISP -> Switch -> WAP -> Modem -> Router -> Máy tính.","Máy tính -> Đường truyền ISP -> Modem -> Switch -> Router.","WAP -> Đường truyền ISP -> Switch -> Router -> Modem."]'::jsonb, 0, 'Thứ tự chuẩn của mạng máy tính phân tầng: ISP cấp tín hiệu vào Modem biến đổi, qua Router định tuyến, tới Switch phân phối dây cho máy bàn và các bộ WAP.', 88) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_089', 'tinhoc', '3', 'mc', 'Một học sinh mang một chiếc Router Wi-Fi cũ của gia đình đến cắm vào cổng LAN của phòng máy trường học để tạo mạng Wi-Fi riêng. Sau đó, toàn bộ máy tính trong phòng máy trường bị mất kết nối mạng Internet. Nguyên nhân kỹ thuật dễ xảy ra nhất là gì?', '["Sóng Wi-Fi từ Router cũ làm đứt các sợi dây cáp mạng trong tường.","Chiếc Router cũ bật sẵn dịch vụ cấp phát địa chỉ IP tự động (DHCP Server), dẫn đến xung đột với máy chủ cấp phát IP của nhà trường (hiện tượng Rogue DHCP Server), khiến các máy tính nhận nhầm Gateway.","Router cũ hút hết băng thông điện áp của phòng máy.","Card mạng của các máy tính phòng thực hành không hỗ trợ kết nối mạng không dây."]'::jsonb, 1, 'Chiếc Router phụ phát sinh dịch vụ DHCP trái phép (Rogue DHCP) cấp dải IP và Gateway sai cho các máy tính khác, dẫn đến mất kết nối mạng toàn phòng.', 89) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_090', 'tinhoc', '3', 'mc', 'Để kết nối hai Switch nằm ở hai tòa nhà cách nhau 800 mét trong khuôn viên trường học, người quản trị mạng nên sử dụng loại cáp truyền dẫn nào là tối ưu và bảo đảm kỹ thuật nhất?', '["Cáp mạng xoắn đôi bấm đầu RJ45 thông thường.","Dây điện thoại 2 lõi bằng đồng.","Cáp quang (Fiber Optic Cable) kết nối qua module quang chuyên dụng trên Switch.","Dây cáp âm thanh analog có vỏ bọc lưới chống nhiễu."]'::jsonb, 2, 'Cáp đồng chỉ truyền được tối đa 100m. Khoảng cách 800m bắt buộc phải sử dụng cáp quang (Fiber Optic) nối giữa hai tòa nhà.', 90) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_091', 'tinhoc', '4', 'mc', 'Giao thức mạng (Network Protocol) được định nghĩa là gì trong lĩnh vực mạng máy tính?', '["Thiết bị phần cứng bảo vệ máy tính khỏi các xung sét điện.","Tập hợp các quy tắc, chuẩn mực quy định cách thức biểu diễn dữ liệu, phát tín hiệu, truyền thông và sửa lỗi giữa các thiết bị kết nối mạng.","Phần mềm diệt virus được cài đặt trên hệ điều hành máy khách.","Hợp đồng kinh tế giữa người sử dụng mạng và nhà cung cấp dịch vụ viễn thông."]'::jsonb, 1, 'Giao thức mạng là tập hợp các quy tắc và chuẩn mực quy định cách các thiết bị trên mạng đóng gói, gửi, nhận và kiểm tra lỗi dữ liệu.', 91) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_092', 'tinhoc', '4', 'mc', 'Bộ giao thức chuẩn đóng vai trò nền tảng cấu thành nên toàn bộ mạng Internet toàn cầu ngày nay là bộ giao thức nào?', '["NetBEUI / IPX.","AppleTalk.","TCP/IP (Transmission Control Protocol / Internet Protocol).","Bluetooth v5.0."]'::jsonb, 2, 'TCP/IP là bộ giao thức nền tảng của mạng Internet toàn cầu từ khi hình thành đến nay.', 92) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_093', 'tinhoc', '4', 'mc', 'Địa chỉ IPv4 theo chuẩn quốc tế có độ dài bao nhiêu bit và được biểu diễn dưới dạng nào cho con người dễ đọc?', '["16 bit, biểu diễn bằng 2 chữ số thập phân.","32 bit, chia làm 4 nhóm (octet), mỗi nhóm 8 bit được viết dưới dạng số thập phân cách nhau bằng dấu chấm (.).","48 bit, chia làm 6 cặp chữ số hệ thập lục phân (hex).","128 bit, chia làm 8 nhóm viết dưới dạng số nhị phân liên tiếp."]'::jsonb, 1, 'IPv4 có độ dài 32 bit, chia làm 4 octet (mỗi octet 8 bit), viết dưới dạng số thập phân có dấu chấm phân cách (Dotted Decimal Notation).', 93) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_094', 'tinhoc', '4', 'mc', 'Giá trị của mỗi số thập phân trong từng octet của địa chỉ IPv4 hợp lệ chỉ được phép nằm trong khoảng nào sau đây?', '["Từ 0 đến 127.","Từ 1 đến 100.","Từ 0 đến 255.","Từ -128 đến +127."]'::jsonb, 2, 'Một octet có 8 bit, giá trị nhị phân từ 00000000 đến 11111111, tương ứng với khoảng thập phân từ 0 đến 255.', 94) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_095', 'tinhoc', '4', 'mc', 'Giao thức nào ở tầng mạng (Internet Layer) chịu trách nhiệm định địa chỉ logic và định tuyến các gói tin qua nhiều mạng khác nhau từ nguồn đến đích?', '["Giao thức IP (Internet Protocol).","Giao thức HTTP.","Giao thức FTP.","Giao thức SMTP."]'::jsonb, 0, 'Giao thức IP (Internet Protocol) ở tầng Internet chịu trách nhiệm gán địa chỉ logic và định tuyến các gói tin xuyên mạng.', 95) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_096', 'tinhoc', '4', 'mc', 'Giao thức TCP (Transmission Control Protocol) thuộc tầng truyền vận có đặc điểm mấu chốt nào sau đây?', '["Truyền dữ liệu hướng kết nối (connection-oriented), bảo đảm độ tin cậy, kiểm tra mất gói tin và tự động yêu cầu truyền lại nếu có lỗi.","Truyền không cần bắt tay, không kiểm tra lỗi và chấp nhận mất mát dữ liệu để đạt tốc độ cao nhất.","Chuyên dùng để phân giải tên miền thành địa chỉ số IP.","Chuyên dùng để gán nhãn địa chỉ MAC cho card mạng."]'::jsonb, 0, 'TCP là giao thức hướng kết nối và đảm bảo độ tin cậy: bảo đảm dữ liệu đến đích toàn vẹn, đúng thứ tự và truyền lại khi bị thất lạc.', 96) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_097', 'tinhoc', '4', 'mc', 'Trong các địa chỉ sau đây, đâu là một địa chỉ IPv4 hợp lệ?', '["192.168.1.300","172.16.256.1","10.0.0.1","192.168.1"]'::jsonb, 2, '10.0.0.1 có đủ 4 nhóm số và các số đều nằm trong khoảng từ 0 đến 255. Các phương án khác vi phạm giới hạn số hoặc thiếu nhóm.', 97) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_098', 'tinhoc', '4', 'mc', 'Địa chỉ IPv4 nào sau đây là không hợp lệ và vì sao?', '["192.168.0.1","203.162.0.181","10.20.30.40","172.300.1.5 vì có octet thứ hai mang giá trị 300 vượt quá giới hạn 255."]'::jsonb, 3, '172.300.1.5 không hợp lệ vì số 300 vượt quá giá trị tối đa 255 của một octet 8 bit.', 98) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_099', 'tinhoc', '4', 'mc', 'Giá trị nhị phân 11000000 của một octet tương ứng với số thập phân nào?', '["128","192","224","240"]'::jsonb, 1, '11000000(2) = 1*2^7 + 1*2^6 = 128 + 64 = 192.', 99) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_100', 'tinhoc', '4', 'mc', 'Số thập phân 255 khi đổi sang hệ nhị phân 8-bit có kết quả là:', '["11111111","10101010","11110000","01111111"]'::jsonb, 0, 'Số 255 đổi sang nhị phân 8-bit là toàn bộ 8 bit 1: 11111111.', 100) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_101', 'tinhoc', '4', 'mc', 'Giao thức DNS (Domain Name System) đóng vai trò tương tự như một ''danh bạ điện thoại'' của mạng Internet nhờ chức năng:', '["Nén dung lượng trang web trước khi tải về máy tính.","Biên dịch tên miền dễ nhớ (ví dụ: moet.gov.vn) thành địa chỉ IP dạng số (ví dụ: 203.162.x.x) để máy tính tìm được máy chủ đích.","Tự động thanh toán tiền cước Internet cho người sử dụng.","Quét virus cho tất cả các bức thư điện tử gửi đi."]'::jsonb, 1, 'DNS giúp con người dễ dàng truy cập mạng bằng tên miền chữ dễ nhớ thay vì phải nhớ dãy số IP phức tạp.', 101) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_102', 'tinhoc', '4', 'mc', 'Sự khác biệt cơ bản giữa giao thức HTTP và giao thức HTTPS khi duyệt web là gì?', '["HTTPS truyền dữ liệu có mã hóa an toàn (thông qua chứng chỉ SSL/TLS), bảo vệ thông tin cá nhân và mật khẩu khỏi bị nghe lén, còn HTTP truyền văn bản thô không mã hóa.","HTTP chỉ xem được hình ảnh, HTTPS chỉ xem được văn bản thuần túy.","HTTP chỉ dùng cho điện thoại di động, HTTPS chỉ dùng cho máy tính bảng.","Tốc độ của HTTP luôn nhanh gấp 100 lần so với HTTPS trong mọi trường hợp."]'::jsonb, 0, 'HTTPS là HTTP có thêm lớp bảo mật mã hóa SSL/TLS, giúp ngăn chặn tin tặc nghe lén hoặc đánh cắp dữ liệu mật khẩu, tài khoản.', 102) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_103', 'tinhoc', '4', 'mc', 'Khi gửi một bức thư điện tử từ máy tính cá nhân lên máy chủ thư điện tử (Mail Server), giao thức truyền thông tiêu chuẩn được sử dụng là:', '["SMTP (Simple Mail Transfer Protocol).","POP3 (Post Office Protocol version 3).","IMAP (Internet Message Access Protocol).","SNMP (Simple Network Management Protocol)."]'::jsonb, 0, 'SMTP (Simple Mail Transfer Protocol) là giao thức chuyên trách cho việc gửi thư điện tử đi.', 103) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_104', 'tinhoc', '4', 'mc', 'Phát biểu nào sau đây phân biệt chính xác giữa hai giao thức nhận thư điện tử POP3 và IMAP?', '["POP3 tải thư về lưu trên một máy tính cá nhân và thường xóa thư trên máy chủ; IMAP đồng bộ hóa thư trực tiếp trên máy chủ, cho phép xem thư trên nhiều thiết bị khác nhau đồng nhất.","POP3 dùng để gửi thư, còn IMAP dùng để nhận thư.","IMAP không hỗ trợ đọc tệp đính kèm, còn POP3 thì có.","POP3 chỉ hoạt động được khi máy tính kết nối mạng qua cáp quang."]'::jsonb, 0, 'POP3 tải thư về máy cục bộ, còn IMAP đồng bộ hóa trực tiếp trên máy chủ giúp người dùng xem thư đồng nhất trên cả máy tính và điện thoại.', 104) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_105', 'tinhoc', '4', 'mc', 'Khi một tệp dữ liệu dung lượng lớn (ví dụ: video 100 MB) được gửi qua mạng Internet bằng giao thức TCP/IP, quá trình nào sẽ diễn ra?', '["Tệp dữ liệu được giữ nguyên thành một khối duy nhất và đẩy thẳng qua đường dây điện.","Tệp dữ liệu được chia nhỏ thành nhiều gói tin (packet), mỗi gói được đánh số thứ tự, gán địa chỉ IP nguồn/đích và gửi độc lập qua mạng; tại nơi nhận, TCP sẽ kiểm tra và lắp ghép lại theo đúng thứ tự.","Máy gửi nén tệp thành định dạng .zip và bắt buộc người nhận phải nhập mật khẩu giải nén.","Tệp dữ liệu chỉ được gửi khi toàn bộ các máy tính trên mạng toàn cầu tạm dừng hoạt động."]'::jsonb, 1, 'Dữ liệu lớn được băm thành các gói nhỏ (packets) gửi độc lập qua các đường truyền khác nhau rồi được TCP tái hợp ráp lại ở đầu nhận.', 105) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_106', 'tinhoc', '4', 'mc', 'Nếu trong quá trình tải tệp qua giao thức TCP, một gói tin bị thất lạc trên đường truyền mạng do nghẽn mạch, cơ chế nào sẽ được kích hoạt?', '["Toàn bộ máy tính người nhận tự động tắt nguồn.","Phía nhận không gửi lại xác nhận (ACK), phía gửi hết thời gian chờ (timeout) sẽ tự động truyền lại gói tin bị mất đó mà không làm hỏng toàn bộ tệp tin.","Tệp tải về bị lỗi vĩnh viễn và người dùng phải cài lại hệ điều hành.","Giao thức IP tự động đổi địa chỉ MAC của người dùng."]'::jsonb, 1, 'TCP có cơ chế kiểm soát truyền lại (Retransmission): khi không nhận được ACK phản hồi của gói tin, phía gửi sẽ tự động gửi lại gói bị thất lạc.', 106) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_107', 'tinhoc', '4', 'mc', 'Chuyển đổi địa chỉ IPv4 192.168.1.1 sang biểu diễn nhị phân tương ứng:', '["11000000.10101000.00000001.00000001","11000000.10101000.00000000.00000001","11110000.10101000.00000001.00000001","11000000.11101000.00000001.00000001"]'::jsonb, 0, '192 = 11000000, 168 = 10101000, 1 = 00000001. Ghép lại: 11000000.10101000.00000001.00000001.', 107) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_108', 'tinhoc', '4', 'mc', 'Ngược lại, dãy bit nhị phân 00001010.00000000.00000000.00000001 tương ứng với địa chỉ IPv4 thập phân nào?', '["10.0.0.1","172.16.0.1","192.168.0.1","10.1.1.1"]'::jsonb, 0, '00001010(2) = 2^3 + 2^1 = 8 + 2 = 10, các nhóm còn lại là 0, 0, 1 -> 10.0.0.1.', 108) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_109', 'tinhoc', '4', 'mc', 'Phân biệt bản chất giữa địa chỉ MAC và địa chỉ IP trong quá trình định tuyến gói tin:', '["Địa chỉ MAC là địa chỉ logic có thể thay đổi; địa chỉ IP là địa chỉ vật lý gắn cứng vào vi mạch.","Địa chỉ IP xác định đường đi từ nguồn đến đích cuối cùng xuyên qua nhiều mạng; địa chỉ MAC xác định chặng truyền trực tiếp giữa hai thiết bị kế cận nhau trong cùng một liên kết mạng cục bộ.","Cả hai địa chỉ đều có độ dài 32 bit và do nhà mạng ISP cung cấp định kỳ.","Địa chỉ MAC chỉ dùng khi duyệt web, địa chỉ IP chỉ dùng khi gửi thư điện tử."]'::jsonb, 1, 'IP xác định hành trình xuyên suốt toàn mạng từ máy gửi đến máy nhận cuối; MAC quản lý việc chuyển tiếp trên từng liên kết vật lý cục bộ giữa hai nút kề cận.', 109) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_110', 'tinhoc', '4', 'mc', 'Khái niệm ''Số hiệu cổng'' (Port Number) trong bộ giao thức TCP/IP dùng để làm gì?', '["Xác định số lượng cổng cắm dây cáp vật lý ở mặt sau của chiếc Router.","Định danh ứng dụng hoặc tiến trình (process) cụ thể trên máy tính đang gửi hoặc nhận dữ liệu (ví dụ: cổng 80 cho HTTP, cổng 443 cho HTTPS).","Đếm số lần máy tính đã khởi động lại trong một tháng.","Đo lường tốc độ vòng quay của quạt tản nhiệt CPU."]'::jsonb, 1, 'Port number ở tầng truyền vận giúp hệ điều hành định tuyến dữ liệu chính xác đến ứng dụng cụ thể đang chạy (như trình duyệt web, phần mềm email).', 110) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_111', 'tinhoc', '4', 'mc', 'Sự khác biệt giữa Định tuyến tĩnh (Static Routing) và Định tuyến động (Dynamic Routing) trên các Router là:', '["Định tuyến tĩnh do người quản trị mạng cấu hình đường đi cố định bằng tay; định tuyến động sử dụng các thuật toán/giao thức định tuyến để Router tự động trao đổi thông tin bảng định tuyến và thích ứng khi có sự cố đứt đường truyền.","Định tuyến tĩnh chỉ dùng cáp quang, định tuyến động chỉ dùng sóng vô tuyến.","Định tuyến tĩnh làm mạng nhanh hơn định tuyến động gấp 10 lần trong mọi tình huống.","Định tuyến tĩnh không cần có địa chỉ IP của mạng đích."]'::jsonb, 0, 'Định tuyến tĩnh cấu hình bằng tay cố định; định tuyến động tự động cập nhật đường đi qua các giao thức định tuyến khi mạng có thay đổi.', 111) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_112', 'tinhoc', '4', 'mc', 'Khi học sinh gõ địa chỉ trang web https://google.com vào trình duyệt nhưng nhận được thông báo lỗi ''DNS_PROBE_FINISHED_NXDOMAIN'', nguyên nhân chính là:', '["Màn hình máy tính bị lỏng dây cáp HDMI.","Máy chủ DNS không thể phân giải tên miền google.com thành địa chỉ IP, có thể do sai tên miền, mất kết nối tới máy chủ DNS hoặc cấu hình DNS bị lỗi.","Bàn phím máy tính bị kẹt phím Enter.","Máy in văn phòng hết giấy in."]'::jsonb, 1, 'NXDOMAIN nghĩa là Non-Existent Domain: máy chủ DNS không tìm thấy bản ghi IP nào tương ứng với tên miền đã gõ.', 112) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_113', 'tinhoc', '4', 'mc', 'Giao thức UDP (User Datagram Protocol) thường được ưu tiên lựa chọn thay thế cho TCP trong trường hợp ứng dụng nào sau đây?', '["Tải tệp cài đặt phần mềm hệ điều hành dạng .iso (yêu cầu chính xác 100% từng bit).","Giao dịch chuyển khoản trực tuyến giữa các tài khoản ngân hàng.","Truyền phát video trực tiếp (Livestream) hoặc gọi điện thoại video thời gian thực, nơi tốc độ mượt mà được ưu tiên hơn việc kiểm tra và truyền lại từng gói tin bị trễ nhỏ.","Gửi văn bản hợp đồng pháp lý qua email."]'::jsonb, 2, 'Livestream và cuộc gọi thoại cần độ trễ thấp tối đa; chấp nhận mất vài gói tin nhỏ không đáng kể thay vì bị dừng chờ truyền lại như TCP.', 113) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_114', 'tinhoc', '4', 'mc', 'Địa chỉ IP nào sau đây thuộc dải địa chỉ riêng tư (Private IP Address) thường dùng trong các mạng LAN nội bộ gia đình và trường học?', '["8.8.8.8","1.1.1.1","192.168.1.10","203.113.131.1"]'::jsonb, 2, '192.168.1.10 thuộc dải IP riêng tư (Private IP) chuẩn Class C (192.168.0.0 - 192.168.255.255) dùng trong mạng nội bộ.', 114) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_115', 'tinhoc', '4', 'mc', 'Một gói tin di chuyển từ máy tính học sinh ở Việt Nam đến máy chủ web đặt tại Hoa Kỳ phải đi qua hàng chục Router trung gian. Tại mỗi Router trung gian dọc đường đi:', '["Địa chỉ IP nguồn và IP đích ban đầu vẫn được giữ nguyên; địa chỉ MAC nguồn và MAC đích sẽ được thay đổi theo từng chặng truyền dẫn cục bộ tương ứng.","Cả địa chỉ IP và địa chỉ MAC đều bị xóa bỏ hoàn toàn.","Nội dung gói tin được nhân bản thành hàng nghìn bản sao gửi đi mọi hướng.","Router trung gian lưu trữ gói tin vĩnh viễn trong ổ cứng của mình."]'::jsonb, 0, 'IP nguồn và IP đích ban đầu được giữ nguyên suốt hành trình; địa chỉ MAC được thay thế liên tục tương ứng với hai đầu của từng chặng liên kết vật lý.', 115) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_116', 'tinhoc', '4', 'mc', 'Tại sao thế giới phải chuyển dịch từ không gian địa chỉ IPv4 sang không gian địa chỉ IPv6?', '["Vì cáp mạng quang không thể truyền được các bit của địa chỉ IPv4.","Vì không gian địa chỉ IPv4 (gồm khoảng 4,3 tỷ địa chỉ) đã hoàn toàn cạn kiệt trước sự bùng nổ của hàng chục tỷ thiết bị thông minh kết nối Internet (IoT).","Vì các máy tính sản xuất sau năm 2020 không còn hỗ trợ hệ điều hành Windows.","Vì IPv4 chỉ cho phép máy tính gửi tin nhắn dưới dạng chữ in hoa."]'::jsonb, 1, 'Không gian 32 bit của IPv4 chỉ cung cấp tối đa khoảng 4,3 tỷ địa chỉ, không đủ cho hàng chục tỷ thiết bị IoT kết nối mạng ngày nay.', 116) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_117', 'tinhoc', '4', 'mc', 'Một máy tính trong phòng thực hành có cấu hình IP tĩnh: Địa chỉ IP 192.168.1.15, Subnet Mask 255.255.255.0, Default Gateway 192.168.1.1. Ý nghĩa của giá trị Default Gateway ở đây là:', '["Địa chỉ của màn hình máy tính hiển thị.","Địa chỉ IP của cổng mạng trên Router mà máy tính sẽ gửi tất cả các gói tin đến khi cần liên lạc với các mạng bên ngoài (Internet).","Mật khẩu bảo vệ card mạng Ethernet.","Tên viết tắt của nhà cung cấp dịch vụ mạng viễn thông."]'::jsonb, 1, 'Default Gateway là địa chỉ ''cổng ra'' của Router trong mạng LAN để chuyển tiếp dữ liệu đến các mạng ngoài.', 117) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_118', 'tinhoc', '4', 'mc', 'Lệnh nào sau đây trong cửa sổ Command Prompt (CMD) của hệ điều hành Windows được dùng để kiểm tra tính thông suốt của đường truyền mạng và đo thời gian phản hồi (Round Trip Time) đến một địa chỉ IP hoặc tên miền?', '["ipconfig /all","ping","format C:","shutdown -s"]'::jsonb, 1, 'Lệnh ping gửi các gói tin ICMP Echo Request để kiểm tra khả năng kết nối và đo độ trễ đường truyền tới máy đích.', 118) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_119', 'tinhoc', '4', 'mc', 'Một học sinh cấu hình thủ công địa chỉ IP cho máy tính của mình như sau: IP Address: 192.168.1.50, Subnet Mask: 255.255.255.0, Gateway: 192.168.1.1, nhưng mục Preferred DNS Server lại để trống. Hiện tượng gì sẽ xảy ra khi học sinh này lướt web?', '["Máy tính hoàn toàn không thể gửi tín hiệu điện áp qua cáp mạng.","Máy tính có thể gõ trực tiếp địa chỉ IP của trang web để truy cập, nhưng không thể mở trang web nếu gõ bằng tên miền chữ (như dantri.com.vn) do thiếu dịch vụ phân giải tên miền.","Bàn phím máy tính bị khóa không thể gõ được chữ cái.","Mọi tệp tin trong ổ cứng máy tính bị chuyển đổi sang hệ nhị phân."]'::jsonb, 1, 'Thiếu cấu hình DNS thì máy không dịch được tên miền thành IP, nên chỉ truy cập được nếu người dùng gõ thẳng địa chỉ IP số của máy chủ web.', 119) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, subject_id, topic_id, type, question_text, options, correct_index, explanation, order_index) VALUES ('tinhoc_mc_120', 'tinhoc', '4', 'mc', 'Phân tích tình huống: Khi máy khách truy cập vào trang web ngân hàng trực tuyến bằng URL https://ebank.vietcombank.com.vn, sự phối hợp nhịp nhàng giữa các giao thức diễn ra theo trình tự hợp lý nào sau đây?', '["HTTP truyền dữ liệu -> DNS tìm địa chỉ MAC -> Bật nguồn máy chủ -> Tắt kết nối TCP.","Trình duyệt gửi truy vấn DNS để lấy IP máy chủ -> Thiết lập kết nối tin cậy TCP (bắt tay 3 bước) -> Thiết lập phiên mã hóa an toàn TLS/HTTPS -> Trao đổi dữ liệu trang web bảo mật.","Gửi thư điện tử qua SMTP -> Định tuyến qua Hub -> Đổi tên miền thành mã nhị phân -> Đóng cổng mạng.","Chạy lệnh ping liên tục -> Tải thư qua POP3 -> Chuyển cáp quang thành cáp đồng -> Kết thúc phiên."]'::jsonb, 1, 'Trình tự chuẩn: Phân giải tên miền (DNS) -> Mở kênh kết nối tin cậy (TCP 3-way handshake) -> Bắt tay mã hóa bảo mật (TLS) -> Trao đổi dữ liệu siêu văn bản an toàn (HTTPS).', 120) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
